"use client";

import { useEffect, useMemo, useState } from "react";
import { useLocale, useTranslations } from "next-intl";
import { PageHeader } from "@/components/page-header";
import { api, formatDate } from "@/lib/api";

type Actor = { id: string | null; name: string | null; email: string | null };
type Entity = { type: string; id: string | null; label: string | null };
type UserOption = { id: string; name: string; email: string };
type Change = { from: unknown; to: unknown };

type Event = {
  id: string;
  event_kind: "security" | "administrative";
  created_at: string;
  actor: Actor;
  module: string;
  action: string;
  entity: Entity;
  source: "UI" | "API" | "SYSTEM" | string;
  reason: string | null;
  before: Record<string, unknown>;
  after: Record<string, unknown>;
  changes: Record<string, unknown>;
  metadata: Record<string, unknown>;
  correlation_id: string | null;
};

const PAGE_SIZE = 50;

const actionModule: Record<string, string> = {
  "user.create": "users",
  "user.update": "users",
  "user.enable": "users",
  "user.disable": "users",
  "user.invite": "users",
  "user.invitation_renew": "users",
  "user.password_reset_issue": "users",
  "user.sessions_revoke": "users",
  "user.mfa_reset": "users",
  "account.create": "accounts",
  "account.update": "accounts",
  "account.enable": "accounts",
  "account.disable": "accounts",
  "account.delete": "accounts",
  "account.connection_test": "accounts",
  "account.schedule_update": "accounts",
  "policy.update": "policies",
  "policy.reset": "policies",
  "pricing.create": "pricing",
  "pricing.update": "pricing",
  "pricing.override": "pricing",
  "pricing.deactivate": "pricing",
  "billing.profile_create": "billing",
  "billing.profile_update": "billing",
  "tls.apply": "tls",
  "tls.mode_change": "tls",
  "opportunity.treat": "opportunities",
  "opportunity.reject": "opportunities",
  "opportunity.reopen": "opportunities",
  "opportunity.archive": "opportunities",
  "opportunity.unarchive": "opportunities",
  "opportunity.bulk_treat": "opportunities",
  "opportunity.bulk_reject": "opportunities",
  "opportunity.bulk_reopen": "opportunities",
};

function fieldLabel(value: string) {
  return value.replaceAll("_", " ").replace(/\b\w/g, (letter) => letter.toUpperCase());
}

function actionLabel(action: string, labels: Record<string, string>) {
  if (labels[action]) return labels[action];
  return action.split(".").map(fieldLabel).join(" · ");
}

type AuditPresentation = { yes: string; no: string; truncated: string; securityEvent: string; updatedItems: (count: number) => string; noDiff: string; unknownActor: string; unauthenticated: string };

function changeValue(value: unknown, words: AuditPresentation): string {
  if (value === null || value === undefined) return "∅";
  if (typeof value === "boolean") return value ? words.yes : words.no;
  if (typeof value === "string" || typeof value === "number") {
    const text = String(value);
    return text.length > 160 ? `${text.slice(0, 157)}…` : text;
  }
  if (Array.isArray(value)) {
    const text = value.map((item) => changeValue(item, words)).join(", ");
    return text.length > 160 ? `${text.slice(0, 157)}…` : text || "[]";
  }
  const text = JSON.stringify(value);
  return text.length > 160 ? `${text.slice(0, 157)}…` : text;
}

function asChange(value: unknown): Change | null {
  if (!value || typeof value !== "object" || Array.isArray(value)) return null;
  if (!("from" in value) || !("to" in value)) return null;
  return value as Change;
}

function changeEntries(item: Event): Array<[string, Change]> {
  return Object.entries(item.changes || {}).flatMap(([field, value]) => {
    const change = asChange(value);
    return change ? [[field, change] as [string, Change]] : [];
  });
}

function changeSummary(item: Event, words: AuditPresentation): string {
  const entries = changeEntries(item);
  if (!entries.length) {
    if (item.changes?._truncated) return words.truncated;
    if (item.event_kind === "security") return item.reason || words.securityEvent;
    const updated = item.metadata?.updated;
    if (typeof updated === "number") return words.updatedItems(updated);
    return words.noDiff;
  }
  const head = entries
    .slice(0, 2)
    .map(([field, change]) => `${fieldLabel(field)}: ${changeValue(change.from, words)} → ${changeValue(change.to, words)}`)
    .join(" · ");
  return entries.length > 2 ? `${head} · +${entries.length - 2}` : head;
}

function actorLabel(item: Event, words: AuditPresentation): { name: string; email: string | null } {
  if (item.actor.name || item.actor.email) {
    return {
      name: item.actor.name || item.actor.email || words.unknownActor,
      email: item.actor.name ? item.actor.email : null,
    };
  }
  if (item.source === "SYSTEM") return { name: "SYSTEM", email: null };
  if (item.action === "auth.login_failed") return { name: words.unauthenticated, email: null };
  return { name: words.unknownActor, email: null };
}

function localDateBoundary(date: string, end: boolean) {
  if (!date) return "";
  const value = new Date(`${date}T${end ? "23:59:59.999" : "00:00:00.000"}`);
  return value.toISOString();
}

function UserAutocomplete({
  label,
  query,
  selectedId,
  onChange,
}: {
  label: string;
  query: string;
  selectedId: string;
  onChange: (query: string, id: string) => void;
}) {
  const t = useTranslations("settings.audit");
  const words: AuditPresentation = {yes:t("presentation.yes"),no:t("presentation.no"),truncated:t("presentation.truncated"),securityEvent:t("presentation.securityEvent"),updatedItems:(count)=>t("presentation.updatedItems", {count}),noDiff:t("presentation.noDiff"),unknownActor:t("presentation.unknownActor"),unauthenticated:t("presentation.unauthenticated")};
  const [options, setOptions] = useState<UserOption[]>([]);
  const [open, setOpen] = useState(false);

  useEffect(() => {
    if (selectedId || query.trim().length < 2) {
      setOptions([]);
      return;
    }
    const controller = new AbortController();
    const timer = window.setTimeout(() => {
      api<UserOption[]>(`/audit/users?q=${encodeURIComponent(query.trim())}&limit=20`, {
        signal: controller.signal,
      })
        .then((items) => {
          setOptions(items);
          setOpen(true);
        })
        .catch(() => setOptions([]));
    }, 300);
    return () => {
      window.clearTimeout(timer);
      controller.abort();
    };
  }, [query, selectedId]);

  return (
    <label style={{ position: "relative" }}>
      {label}
      <input
        value={query}
        maxLength={254}
        placeholder={t("nameOrEmail")}
        onFocus={() => setOpen(true)}
        onChange={(event) => onChange(event.target.value, "")}
      />
      {selectedId && <span>{t("selectedUser")}</span>}
      {open && !selectedId && options.length > 0 && (
        <div
          role="listbox"
          style={{
            position: "absolute",
            zIndex: 20,
            top: "100%",
            left: 0,
            right: 0,
            maxHeight: 240,
            overflowY: "auto",
            border: "1px solid var(--border)",
            borderRadius: "var(--radius-control)",
            background: "var(--surface)",
            boxShadow: "var(--shadow)",
            padding: "var(--space-2)",
          }}
        >
          {options.map((option) => (
            <button
              type="button"
              key={option.id}
              role="option"
              aria-selected={option.id === selectedId}
              className="button"
              style={{ width: "100%", textAlign: "left", marginBottom: "var(--space-1)" }}
              onClick={() => {
                onChange(`${option.name} — ${option.email}`, option.id);
                setOpen(false);
              }}
            >
              <strong>{option.name}</strong> · {option.email}
            </button>
          ))}
        </div>
      )}
    </label>
  );
}

export default function AuditPage() {
  const locale = useLocale();
  const t = useTranslations("settings.audit");
  const words: AuditPresentation = {yes:t("presentation.yes"),no:t("presentation.no"),truncated:t("presentation.truncated"),securityEvent:t("presentation.securityEvent"),updatedItems:(count)=>t("presentation.updatedItems", {count}),noDiff:t("presentation.noDiff"),unknownActor:t("presentation.unknownActor"),unauthenticated:t("presentation.unauthenticated")};
  const localizedEvents: Record<string, string> = {
    "auth.login": t("events.authLogin"),
    "auth.login_failed": t("events.authLoginFailed"),
    "auth.logout": t("events.authLogout"),
    "auth.logout_all": t("events.authLogoutAll"),
    "auth.session_revoked": t("events.authSessionRevoked"),
    "auth.reauthenticated": t("events.authReauthenticated"),
    "auth.password_changed": t("events.authPasswordChanged"),
    "auth.password_reset": t("events.authPasswordReset"),
    "auth.invitation_accepted": t("events.authInvitationAccepted"),
    "user.created": t("events.userCreated"),
    "user.updated": t("events.userUpdated"),
    "user.invited": t("events.userInvited"),
    "user.invitation_renewed": t("events.userInvitationRenewed"),
    "user.password_reset_issued": t("events.userPasswordResetIssued"),
    "user.sessions_revoked": t("events.userSessionsRevoked"),
    "user.session_revoked": t("events.userSessionRevoked"),
    "user.create": t("events.userCreate"),
    "user.update": t("events.userUpdate"),
    "user.enable": t("events.userEnable"),
    "user.disable": t("events.userDisable"),
    "user.invite": t("events.userInvite"),
    "user.invitation_renew": t("events.userInvitationRenew"),
    "user.password_reset_issue": t("events.userPasswordResetIssue"),
    "user.sessions_revoke": t("events.userSessionsRevoke"),
    "user.mfa_reset": t("events.userMfaReset"),
    "mfa.setup_started": t("events.mfaSetupStarted"),
    "mfa.enabled": t("events.mfaEnabled"),
    "mfa.login_failed": t("events.mfaLoginFailed"),
    "mfa.login_verified": t("events.mfaLoginVerified"),
    "mfa.recovery_used": t("events.mfaRecoveryUsed"),
    "mfa.recovery_regenerated": t("events.mfaRecoveryRegenerated"),
    "mfa.reset": t("events.mfaReset"),
    "account.create": t("events.accountCreate"),
    "account.update": t("events.accountUpdate"),
    "account.enable": t("events.accountEnable"),
    "account.disable": t("events.accountDisable"),
    "account.delete": t("events.accountDelete"),
    "account.connection_test": t("events.accountConnectionTest"),
    "account.schedule_update": t("events.accountScheduleUpdate"),
    "policy.update": t("events.policyUpdate"),
    "policy.reset": t("events.policyReset"),
    "pricing.create": t("events.pricingCreate"),
    "pricing.update": t("events.pricingUpdate"),
    "pricing.override": t("events.pricingOverride"),
    "pricing.deactivate": t("events.pricingDeactivate"),
    "billing.profile_create": t("events.billingProfileCreate"),
    "billing.profile_update": t("events.billingProfileUpdate"),
    "tls.apply": t("events.tlsApply"),
    "tls.mode_change": t("events.tlsModeChange"),
    "opportunity.treat": t("events.opportunityTreat"),
    "opportunity.reject": t("events.opportunityReject"),
    "opportunity.reopen": t("events.opportunityReopen"),
    "opportunity.archive": t("events.opportunityArchive"),
    "opportunity.unarchive": t("events.opportunityUnarchive"),
    "opportunity.bulk_treat": t("events.opportunityBulkTreat"),
    "opportunity.bulk_reject": t("events.opportunityBulkReject"),
    "opportunity.bulk_reopen": t("events.opportunityBulkReopen"),
  };
  const modules: Array<readonly [string, string]> = [["",t("all")],["users",t("modules.users")],["security",t("modules.security")],["auth",t("modules.auth")],["mfa","MFA"],["accounts",t("modules.accounts")],["policies",t("modules.policies")],["opportunities",t("modules.opportunities")],["pricing",t("modules.pricing")],["billing","Billing"],["tls","HTTPS"]];
  const initial = useMemo(() => {
    if (typeof window === "undefined") return new URLSearchParams();
    return new URLSearchParams(window.location.search);
  }, []);
  const [eventKind, setEventKind] = useState(initial.get("event_kind") || "all");
  const [actorQuery, setActorQuery] = useState(initial.get("actor_search") || "");
  const [actorId, setActorId] = useState(initial.get("actor_id") || "");
  const [subjectQuery, setSubjectQuery] = useState(initial.get("subject_user_search") || "");
  const [subjectId, setSubjectId] = useState(initial.get("subject_user_id") || "");
  const [module, setModule] = useState(initial.get("module") || "");
  const [action, setAction] = useState(initial.get("action") || "");
  const [source, setSource] = useState(initial.get("source") || "");
  const [fromIso, setFromIso] = useState(initial.get("from") || "");
  const [toIso, setToIso] = useState(initial.get("to") || "");
  const [offset, setOffset] = useState(Number(initial.get("offset") || 0));
  const [refresh, setRefresh] = useState(0);
  const [data, setData] = useState<{ items: Event[]; total: number }>({ items: [], total: 0 });
  const [busy, setBusy] = useState(true);
  const [error, setError] = useState("");
  const [selected, setSelected] = useState<Event | null>(null);

  const availableActions = Object.keys(actionModule)
    .filter((key) => !module || actionModule[key] === module)
    .sort((a, b) => actionLabel(a, localizedEvents).localeCompare(actionLabel(b, localizedEvents)));

  const query = useMemo(() => {
    const params = new URLSearchParams({
      limit: String(PAGE_SIZE),
      offset: String(offset),
      event_kind: eventKind,
    });
    if (actorId) params.set("actor_id", actorId);
    else if (actorQuery.trim()) params.set("actor_search", actorQuery.trim());
    if (subjectId) params.set("subject_user_id", subjectId);
    else if (subjectQuery.trim()) params.set("subject_user_search", subjectQuery.trim());
    if (module) params.set("module", module);
    if (action) params.set("action", action);
    if (source) params.set("source", source);
    if (fromIso) params.set("from", fromIso);
    if (toIso) params.set("to", toIso);
    return params;
  }, [eventKind, actorId, actorQuery, subjectId, subjectQuery, module, action, source, fromIso, toIso, offset]);

  useEffect(() => {
    const visible = new URLSearchParams(query);
    visible.delete("limit");
    if (visible.get("offset") === "0") visible.delete("offset");
    window.history.replaceState(null, "", `${window.location.pathname}${visible.size ? `?${visible}` : ""}`);
  }, [query]);

  useEffect(() => {
    let active = true;
    const controller = new AbortController();
    setBusy(true);
    setError("");
    api<{ items: Event[]; total: number }>(`/audit?${query}`, { signal: controller.signal })
      .then((result) => {
        if (active) setData(result);
      })
      .catch((err) => {
        if (active && err.name !== "AbortError") setError(err.message);
      })
      .finally(() => {
        if (active) setBusy(false);
      });
    return () => {
      active = false;
      controller.abort();
    };
  }, [query, refresh]);

  function resetPagination() {
    setOffset(0);
  }

  function applyPreset(hours: number) {
    const now = new Date();
    const start = new Date(now.getTime() - hours * 60 * 60 * 1000);
    setFromIso(start.toISOString());
    setToIso(now.toISOString());
    resetPagination();
  }

  function clearFilters() {
    setEventKind("all");
    setActorQuery("");
    setActorId("");
    setSubjectQuery("");
    setSubjectId("");
    setModule("");
    setAction("");
    setSource("");
    setFromIso("");
    setToIso("");
    setOffset(0);
  }

  const activeFilters = [
    actorQuery && t("filterActor", {value:actorQuery}),
    subjectQuery && t("filterSubject", {value:subjectQuery}),
    module && t("filterModule", {value:modules.find(([value]) => value === module)?.[1] || module}),
    action && t("filterAction", {value:actionLabel(action, localizedEvents)}),
    source && t("filterSource", {value:source}),
    eventKind !== "all" && t("filterKind", {value:eventKind === "security" ? t("security") : t("administrative")}),
    fromIso && t("filterFrom", {value:formatDate(fromIso, locale)}),
    toIso && t("filterTo", {value:formatDate(toIso, locale)}),
  ].filter(Boolean) as string[];

  return (
    <>
      <PageHeader
        eyebrow={t("eyebrow")}
        title={t("title")}
        description={t("description")}
        actions={
          <button className="button" disabled={busy} onClick={() => setRefresh((value) => value + 1)}>
            {t("refresh")}
          </button>
        }
      />

      <p className="settings-help">
        {t("help")}
      </p>

      <div className="settings-filters">
        <UserAutocomplete
          label={t("actor")}
          query={actorQuery}
          selectedId={actorId}
          onChange={(value, id) => {
            setActorQuery(value);
            setActorId(id);
            resetPagination();
          }}
        />
        <UserAutocomplete
          label={t("subject")}
          query={subjectQuery}
          selectedId={subjectId}
          onChange={(value, id) => {
            setSubjectQuery(value);
            setSubjectId(id);
            resetPagination();
          }}
        />
        <label>
          {t("module")}
          <select
            value={module}
            onChange={(event) => {
              const value = event.target.value;
              setModule(value);
              if (action && value && actionModule[action] !== value) setAction("");
              resetPagination();
            }}
          >
            {modules.map(([value, label]) => (
              <option key={value} value={value}>{label}</option>
            ))}
          </select>
        </label>
        <label>
          {t("action")}
          <select value={action} onChange={(event) => { setAction(event.target.value); resetPagination(); }}>
            <option value="">{t("allFeminine")}</option>
            {availableActions.map((value) => (
              <option key={value} value={value}>{actionLabel(value, localizedEvents)}</option>
            ))}
          </select>
        </label>
        <label>
          {t("source")}
          <select value={source} onChange={(event) => { setSource(event.target.value); resetPagination(); }}>
            <option value="">{t("allFeminine")}</option>
            <option value="UI">UI</option>
            <option value="API">API</option>
            <option value="SYSTEM">SYSTEM</option>
          </select>
        </label>
        <label>
          {t("eventKind")}
          <select value={eventKind} onChange={(event) => { setEventKind(event.target.value); resetPagination(); }}>
            <option value="all">{t("all")}</option>
            <option value="administrative">{t("administrativePlural")}</option>
            <option value="security">{t("security")}</option>
          </select>
        </label>
        <label>
          {t("dateFrom")}
          <input
            type="date"
            value={fromIso ? fromIso.slice(0, 10) : ""}
            onChange={(event) => { setFromIso(localDateBoundary(event.target.value, false)); resetPagination(); }}
          />
        </label>
        <label>
          {t("dateTo")}
          <input
            type="date"
            value={toIso ? toIso.slice(0, 10) : ""}
            onChange={(event) => { setToIso(localDateBoundary(event.target.value, true)); resetPagination(); }}
          />
        </label>
      </div>

      <div style={{ display: "flex", flexWrap: "wrap", gap: "var(--space-2)", marginBottom: "var(--space-4)" }}>
        <button className="button" onClick={() => applyPreset(24)}>{t("last24h")}</button>
        <button className="button" onClick={() => applyPreset(24 * 7)}>{t("last7d")}</button>
        <button className="button" onClick={() => applyPreset(24 * 30)}>{t("last30d")}</button>
        <button
          className="button"
          onClick={() => {
            const now = new Date();
            const start = new Date(now);
            start.setHours(0, 0, 0, 0);
            setFromIso(start.toISOString());
            setToIso(now.toISOString());
            resetPagination();
          }}
        >
          {t("today")}
        </button>
        <button className="button" onClick={clearFilters}>{t("clear")}</button>
      </div>

      <div style={{ display: "flex", flexWrap: "wrap", gap: "var(--space-2)", marginBottom: "var(--space-4)", alignItems: "center" }}>
        <strong>{t("totalEvents", {count:data.total})}</strong>
        {activeFilters.map((filter) => (
          <span
            key={filter}
            style={{
              padding: "var(--space-1) var(--space-2)",
              border: "1px solid var(--border)",
              borderRadius: "var(--radius-pill)",
            }}
          >
            {filter}
          </span>
        ))}
      </div>

      {error && <p className="form-error" role="alert">{error}</p>}

      <div className="data-table-wrap">
        <table className="data-table" aria-label={t("tableAria")}>
          <thead>
            <tr>
              <th scope="col">{t("dateTime")}</th>
              <th scope="col">{t("event")}</th>
              <th scope="col">{t("responsible")}</th>
              <th scope="col">{t("entity")}</th>
              <th scope="col">{t("changes")}</th>
              <th scope="col">{t("source")}</th>
            </tr>
          </thead>
          <tbody>
            {busy ? (
              <tr><td colSpan={6}>{t("loading")}</td></tr>
            ) : data.items.length === 0 ? (
              <tr><td colSpan={6}>{t("empty")}</td></tr>
            ) : (
              data.items.map((item) => {
                const actor = actorLabel(item, words);
                return (
                  <tr key={`${item.event_kind}:${item.id}`}>
                    <td><span>{formatDate(item.created_at, locale)}</span></td>
                    <td>
                      <strong>{actionLabel(item.action, localizedEvents)}</strong>
                      <span>{modules.find(([key]) => key === item.module)?.[1] || item.module} · {item.event_kind === "administrative" ? t("administrative") : t("security")}</span>
                    </td>
                    <td>
                      <strong>{actor.name}</strong>
                      {actor.email && <span>{actor.email}</span>}
                    </td>
                    <td>
                      <strong>{item.entity.label || item.entity.id || "—"}</strong>
                      <span>{item.entity.type}{item.entity.id ? ` · ${item.entity.id}` : ""}</span>
                    </td>
                    <td>
                      <span>{changeSummary(item, words)}</span>
                      <button className="button" onClick={() => setSelected(item)}>{t("details")}</button>
                    </td>
                    <td><strong>{item.source}</strong></td>
                  </tr>
                );
              })
            )}
          </tbody>
        </table>
      </div>

      <div className="settings-pagination">
        <button className="button" disabled={busy || offset === 0} onClick={() => setOffset(Math.max(0, offset - PAGE_SIZE))}>
          {t("previous")}
        </button>
        <span>{t("pagination", {count:data.total, page:Math.floor(offset / PAGE_SIZE) + 1})}</span>
        <button className="button" disabled={busy || offset + PAGE_SIZE >= data.total} onClick={() => setOffset(offset + PAGE_SIZE)}>
          {t("next")}
        </button>
      </div>

      {selected && (
        <div
          role="dialog"
          aria-modal="true"
          aria-label={t("detailsAria")}
          style={{ position: "fixed", inset: 0, zIndex: 100, background: "var(--overlay)", display: "flex", justifyContent: "flex-end" }}
          onClick={() => setSelected(null)}
        >
          <section
            style={{ width: "min(720px, 100%)", height: "100%", overflowY: "auto", background: "var(--surface)", padding: "var(--space-6)" }}
            onClick={(event) => event.stopPropagation()}
          >
            <div style={{ display: "flex", justifyContent: "space-between", gap: "var(--space-4)", alignItems: "flex-start" }}>
              <div>
                <span>{t("detailsHeading")}</span>
                <h2>{actionLabel(selected.action, localizedEvents)}</h2>
              </div>
              <button className="button" onClick={() => setSelected(null)}>{t("close")}</button>
            </div>
            <dl>
              <dt>{t("date")}</dt><dd>{formatDate(selected.created_at, locale)}</dd>
              <dt>{t("responsible")}</dt><dd>{actorLabel(selected, words).name}</dd>
              <dt>{t("responsibleEmail")}</dt><dd>{selected.actor.email || "—"}</dd>
              <dt>{t("module")}</dt><dd>{modules.find(([key]) => key === selected.module)?.[1] || selected.module}</dd>
              <dt>{t("source")}</dt><dd>{selected.source}</dd>
              <dt>{t("entity")}</dt><dd>{selected.entity.label || "—"}</dd>
              <dt>{t("entityId")}</dt><dd style={{ overflowWrap: "anywhere" }}>{selected.entity.id || "—"}</dd>
              <dt>Correlation ID</dt><dd style={{ overflowWrap: "anywhere" }}>{selected.correlation_id || "—"}</dd>
            </dl>

            <h3>{t("changes")}</h3>
            {changeEntries(selected).length ? (
              <div className="data-table-wrap">
                <table className="data-table">
                  <thead><tr><th>{t("field")}</th><th>{t("before")}</th><th>{t("after")}</th></tr></thead>
                  <tbody>
                    {changeEntries(selected).map(([field, change]) => (
                      <tr key={field}>
                        <td><strong>{fieldLabel(field)}</strong></td>
                        <td style={{ overflowWrap: "anywhere" }}>{changeValue(change.from, words)}</td>
                        <td style={{ overflowWrap: "anywhere" }}>{changeValue(change.to, words)}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            ) : (
              <p>{selected.reason || t("noDiff")}</p>
            )}

            {Object.keys(selected.metadata || {}).length > 0 && (
              <>
                <h3>{t("safeContext")}</h3>
                <div className="data-table-wrap">
                  <table className="data-table">
                    <tbody>
                      {Object.entries(selected.metadata).map(([key, value]) => (
                        <tr key={key}><th>{fieldLabel(key)}</th><td style={{ overflowWrap: "anywhere" }}>{changeValue(value, words)}</td></tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </>
            )}
          </section>
        </div>
      )}
    </>
  );
}

frontend/app/settings/billing/profiles/p.source:
"use client";

import { useCallback, useEffect, useState } from "react";
import { useTranslations } from "next-intl";
import { PageHeader, Section, StatusIndicator } from "@/components/aven";
import {
  Alert,
  Badge,
  Button,
  Checkbox,
  Input,
  Select,
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
  TableState,
} from "@/components/ui";
import {
  BillingGranularity,
  BillingGroupBy,
  BillingMetric,
  BillingProfile,
  BillingProfileInput,
  createBillingProfile,
  deactivateBillingProfile,
  listBillingProfiles,
  setDefaultBillingProfile,
  updateBillingProfile,
} from "@/lib/billing";
import styles from "../../settings-page.module.css";

const RECORD_TYPES = [
  "Credit",
  "DiscountedUsage",
  "Fee",
  "Refund",
  "RIFee",
  "SavingsPlanCoveredUsage",
  "SavingsPlanNegation",
  "SavingsPlanRecurringFee",
  "SavingsPlanUpfrontFee",
  "Tax",
  "Usage",
];

type FormState = BillingProfileInput & { id?: string };

const emptyForm: FormState = {
  name: "",
  description: "",
  granularity: "DAILY",
  metric: "AMORTIZED_COST",
  group_by: "NONE",
  exclude_record_types: ["Credit"],
  is_default: false,
};

function message(error: unknown, fallback: string) {
  return error instanceof Error ? error.message : fallback;
}

function profileSummary(profile: BillingProfile, metrics: Record<BillingMetric, string>, granularities: Record<BillingGranularity, string>, emptyLabel: string, excludeLabel: (types: string) => string) {
  const exclusions = profile.exclude_record_types.length
    ? excludeLabel(profile.exclude_record_types.join(", "))
     : emptyLabel;
  return `${granularities[profile.granularity]} · ${metrics[profile.metric]} · ${exclusions}`;
}

export default function BillingProfilesPage() {
  const t = useTranslations("settings.billingProfiles");
  const metricLabels: Record<BillingMetric, string> = { AMORTIZED_COST: t("metrics.amortized"), NET_AMORTIZED_COST: t("metrics.netAmortized"), UNBLENDED_COST: t("metrics.unblended") };
  const granularityLabels: Record<BillingGranularity, string> = { DAILY: t("granularity.daily"), MONTHLY: t("granularity.monthly") };
  const groupingLabels: Record<BillingGroupBy, string> = { NONE: t("grouping.none"), SERVICE: t("grouping.service"), ACCOUNT: t("grouping.account") };
  const [profiles, setProfiles] = useState<BillingProfile[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState<{kind: "updated" | "created" | "default" | "deactivated"; name: string} | null>(null);
  const [form, setForm] = useState<FormState | null>(null);

  const load = useCallback(async () => {
    setLoading(true);
    setError("");
    try {
      setProfiles(await listBillingProfiles());
    } catch (err) {
      setError(message(err, "ERR_BILLING_PROFILES_LOAD"));
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    void load();
  }, [load]);

  function edit(profile: BillingProfile) {
    setForm({
      id: profile.id,
      name: profile.name,
      description: profile.description ?? "",
      granularity: profile.granularity,
      metric: profile.metric,
      group_by: profile.group_by,
      exclude_record_types: [...profile.exclude_record_types],
    });
  }

  async function submit(event: React.FormEvent) {
    event.preventDefault();
    if (!form) return;
    setSaving(true);
    setError("");
    setSuccess(null);
    const payload: BillingProfileInput = {
      name: form.name.trim(),
      description: form.description?.trim() || null,
      granularity: form.granularity,
      metric: form.metric,
      group_by: form.group_by,
      exclude_record_types: form.exclude_record_types,
      is_default: form.is_default,
    };
    try {
      if (form.id) {
        await updateBillingProfile(form.id, payload);
        setSuccess({kind: "updated", name: payload.name});
      } else {
        await createBillingProfile(payload);
        setSuccess({kind: "created", name: payload.name});
      }
      setForm(null);
      await load();
    } catch (err) {
      setError(message(err, "ERR_BILLING_PROFILES_SAVE"));
    } finally {
      setSaving(false);
    }
  }

  async function setDefault(profile: BillingProfile) {
    setError("");
    setSuccess(null);
    try {
      await setDefaultBillingProfile(profile.id);
      setSuccess({kind: "default", name: profile.name});
      await load();
    } catch (err) {
      setError(message(err, "ERR_BILLING_PROFILES_DEFAULT"));
    }
  }

  async function deactivate(profile: BillingProfile) {
    setError("");
    setSuccess(null);
    try {
      await deactivateBillingProfile(profile.id);
      setSuccess({kind: "deactivated", name: profile.name});
      await load();
    } catch (err) {
      setError(message(err, "ERR_BILLING_PROFILES_DEACTIVATE"));
    }
  }

  return (
    <>
      <PageHeader
        title={t("title")}
        description={t("description")}
        actions={<Button onClick={() => setForm({ ...emptyForm })}>{t("newProfile")}</Button>}
      />

      {error && <Alert variant="danger" title={t("errorTitle")} description={error === "ERR_BILLING_PROFILES_LOAD" ? t("errors.load") : error === "ERR_BILLING_PROFILES_SAVE" ? t("errors.save") : error === "ERR_BILLING_PROFILES_DEFAULT" ? t("errors.setDefault") : error === "ERR_BILLING_PROFILES_DEACTIVATE" ? t("errors.deactivate") : error} />}
      {success && <Alert variant="success" title={t("successTitle")} description={success.kind === "updated" ? t("success.updated", {name: success.name}) : success.kind === "created" ? t("success.created", {name: success.name}) : success.kind === "default" ? t("success.default", {name: success.name}) : t("success.deactivated", {name: success.name})} />}

      {form && (
        <Section
          appearance="card"
          title={form.id ? t("editProfile") : t("newProfile")}
          description={t("saveNote")}
        >
          <form onSubmit={submit} className={styles.formStack}>
            <div className={styles.formGrid}>
              <Input
                label={t("name")}
                required
                maxLength={120}
                value={form.name}
                onChange={(event) => setForm({ ...form, name: event.target.value })}
              />
              <Input
                label={t("descriptionLabel")}
                maxLength={1000}
                value={form.description ?? ""}
                onChange={(event) => setForm({ ...form, description: event.target.value })}
              />
              <Select
                label={t("metric")}
                value={form.metric}
                onChange={(event) => setForm({ ...form, metric: event.target.value as BillingMetric })}
                options={Object.entries(metricLabels).map(([value, label]) => ({ value, label }))}
              />
              <Select
                label={t("granularityLabel")}
                value={form.granularity}
                onChange={(event) => setForm({ ...form, granularity: event.target.value as BillingGranularity })}
                options={Object.entries(granularityLabels).map(([value, label]) => ({ value, label }))}
              />
              <Select
                label={t("defaultGrouping")}
                value={form.group_by}
                onChange={(event) => setForm({ ...form, group_by: event.target.value as BillingGroupBy })}
                options={Object.entries(groupingLabels).map(([value, label]) => ({ value, label }))}
              />
              {!form.id && (
                <Checkbox
                  label={t("setDefault")}
                  checked={Boolean(form.is_default)}
                  onChange={(event) => setForm({ ...form, is_default: event.target.checked })}
                />
              )}
            </div>

            <fieldset className={styles.formStack}>
              <legend>{t("excludeRecordTypes")}</legend>
              <div className={styles.checkboxGrid}>
                {RECORD_TYPES.map((recordType) => {
                  const checked = form.exclude_record_types.includes(recordType);
                  return (
                    <Checkbox
                      key={recordType}
                      label={recordType}
                      checked={checked}
                      onChange={(event) => {
                        const next = event.target.checked
                          ? [...form.exclude_record_types, recordType]
                          : form.exclude_record_types.filter((item) => item !== recordType);
                        setForm({ ...form, exclude_record_types: next });
                      }}
                    />
                  );
                })}
              </div>
            </fieldset>

            <div className={styles.formActions}>
              <Button type="submit" loading={saving}>{t("save")}</Button>
              <Button variant="ghost" onClick={() => setForm(null)} disabled={saving}>{t("cancel")}</Button>
            </div>
          </form>
        </Section>
      )}

      <Section title={t("availableTitle")} description={t("availableDescription")}>
        <Table aria-label={t("tableLabel")}>
          <TableHeader>
            <TableRow staticRow>
              <TableHead>{t("column.profile")}</TableHead>
              <TableHead>{t("column.config")}</TableHead>
              <TableHead>{t("column.grouping")}</TableHead>
              <TableHead>{t("column.status")}</TableHead>
              <TableHead>{t("column.actions")}</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {loading ? (
              <TableRow staticRow>
                <TableState state="loading" colSpan={5}>{t("loading")}</TableState>
              </TableRow>
            ) : profiles.length === 0 ? (
              <TableRow staticRow>
                <TableState state="empty" colSpan={5}>{t("empty")}</TableState>
              </TableRow>
            ) : profiles.map((profile) => (
              <TableRow key={profile.id}>
                <TableCell>
                  <div className={styles.stack}>
                    <div className={styles.inlineMeta}>
                      <strong>{profile.name}</strong>
                      {profile.is_default && <Badge variant="info" appearance="subtle">{t("default")}</Badge>}
                    </div>
                    <span className={styles.secondaryText}>
                      {profile.description || (profile.is_system ? t("systemProfile") : t("noDescription"))}
                    </span>
                  </div>
                </TableCell>
                <TableCell>{profileSummary(profile, metricLabels, granularityLabels, t("noExclusions"), (types) => t("excludes", {types}))}</TableCell>
                <TableCell>{groupingLabels[profile.group_by]}</TableCell>
                <TableCell>
                  <StatusIndicator
                    status={profile.enabled ? "success" : "neutral"}
                    label={profile.enabled ? t("active") : t("inactive")}
                  />
                </TableCell>
                <TableCell>
                  <div className={styles.formActions}>
                    <Button size="sm" variant="ghost" onClick={() => edit(profile)} disabled={!profile.enabled}>
                      {t("edit")}
                    </Button>
                    {!profile.is_default && profile.enabled && (
                      <Button size="sm" variant="outline" onClick={() => void setDefault(profile)}>
                        {t("setDefault")}
                      </Button>
                    )}
                    {!profile.is_default && !profile.is_system && profile.enabled && (
                      <Button size="sm" variant="danger" onClick={() => void deactivate(profile)}>
                        {t("deactivate")}
                      </Button>
                    )}
                  </div>
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </Section>
    </>
  );
}

frontend/app/settings/https/page.tsx.source:
"use client";

import { FormEvent, useEffect, useState } from "react";
import { useLocale, useTranslations } from "next-intl";
import { IdentityProof } from "@/components/identity-proof";
import { PageHeader } from "@/components/page-header";
import { api, ApiError, formatDate } from "@/lib/api";

type CertificateInfo = {
  fingerprint_sha256: string;
  issuer: string;
  valid_from: string;
  valid_until: string;
  san: string[];
  chain_length?: number;
};

type LocalTls = {
  healthy: boolean;
  trusted: boolean | null;
  trust_error: string | null;
  certificate: CertificateInfo | null;
  message: string;
};

type Endpoint = {
  record_type: "A" | "AAAA";
  address: string;
  status: "VERIFIED" | "PARTIAL" | "MISMATCH" | "UNREACHABLE";
  fingerprint_matches: boolean | null;
  hostname_valid: boolean;
  trusted: boolean | null;
  message: string;
};

type EndpointValidation = {
  status:
    | "VERIFIED"
    | "PARTIAL"
    | "MISMATCH"
    | "UNREACHABLE"
    | "DNS_NOT_FOUND";
  endpoints: Endpoint[];
  message: string;
};

type ChainInfo = {
  status: "VALID" | "UNANCHORED";
  provided_intermediates: number;
  served_intermediates: number;
  served_chain_length: number;
  root_omitted: boolean;
  root_subject: string | null;
  message: string;
};

type TrustInfo = {
  status:
    | "PUBLIC_TRUSTED"
    | "PRIVATE_OR_UNTRUSTED"
    | "UNTRUSTED_OR_INCOMPLETE"
    | "UNANCHORED";
  message: string;
};

type TlsStatus = {
  configured: boolean;
  mode: "http" | "automatic" | "custom";
  domain: string | null;
  healthy: boolean;
  local_tls: LocalTls;
  dns: { a: string[]; aaaa: string[] };
  endpoint_validation: EndpointValidation;
  certificate: CertificateInfo | null;
  chain: ChainInfo | null;
  trust: TrustInfo | null;
  applied_at: string | null;
  last_validated_at: string | null;
  message: string;
};

type ValidationResult = {
  valid: boolean;
  mode: "automatic" | "custom";
  domain: string;
  certificate: CertificateInfo | null;
  chain: ChainInfo | null;
  trust: TrustInfo | null;
};

export default function HttpsSettingsPage() {
  const locale = useLocale();
  const t = useTranslations("settings.https");
  const endpointLabels: Record<EndpointValidation["status"], string> = {
    VERIFIED: t("endpointVerified"),
    PARTIAL: t("endpointPartial"),
    MISMATCH: t("endpointMismatch"),
    UNREACHABLE: t("endpointUnreachable"),
    DNS_NOT_FOUND: t("endpointDnsNotFound"),
  };
  const trustLabel = (trust: TrustInfo | null) => !trust
    ? t("trustNotEvaluated")
    : trust.status === "PUBLIC_TRUSTED"
      ? t("trustPublic")
      : trust.status === "PRIVATE_OR_UNTRUSTED"
        ? t("trustPrivate")
        : t("trustAttention");
  const [status, setStatus] = useState<TlsStatus | null>(null);
  const [mode, setMode] = useState<"automatic" | "custom">("automatic");
  const [domain, setDomain] = useState("");
  const [serverCertificate, setServerCertificate] = useState("");
  const [intermediateChain, setIntermediateChain] = useState("");
  const [privateKey, setPrivateKey] = useState("");
  const [validation, setValidation] = useState<ValidationResult | null>(null);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [message, setMessage] = useState("");

  async function load(initial = false) {
    const next = await api<TlsStatus>("/tls");
    setStatus(next);
    if (initial && next.configured && next.domain) {
      setDomain(next.domain);
      if (next.mode === "automatic" || next.mode === "custom") {
        setMode(next.mode);
      }
    }
  }

  useEffect(() => {
    load(true).catch((err) =>
      setError(
        err instanceof Error ? err.message : t("loadError"),
      ),
    );
  }, []);

  function payload() {
    return {
      mode,
      domain,
      server_certificate: mode === "custom" ? serverCertificate : "",
      intermediate_chain: mode === "custom" ? intermediateChain : "",
      private_key: mode === "custom" ? privateKey : undefined,
    };
  }

  async function run(action: "validate" | "apply") {
    setBusy(true);
    setError("");
    setMessage("");
    try {
      if (action === "validate") {
        const result = await api<ValidationResult>("/tls/validate", {
          method: "POST",
          body: JSON.stringify(payload()),
        });
        setValidation(result);
        setMessage(
          result.mode === "custom"
            ? t("validatedCustom")
            : t("validatedAutomatic"),
        );
      } else {
        const result = await api<TlsStatus>("/tls/apply", {
          method: "POST",
          body: JSON.stringify(payload()),
        });
        setStatus(result);
        setValidation(null);
        setServerCertificate("");
        setIntermediateChain("");
        setPrivateKey("");
        setMessage(
          t("appliedMessage"),
        );
      }
    } catch (err) {
      setValidation(null);
      if (
        err instanceof ApiError &&
        err.detail === "reauthentication_required"
      ) {
        setError(
          t("reauthRequired"),
        );
        document
          .getElementById("identity-proof")
          ?.scrollIntoView({ behavior: "smooth" });
      } else {
        setError(
          err instanceof Error
            ? err.message
            : t("operationError"),
        );
      }
    } finally {
      setBusy(false);
    }
  }

  function submit(event: FormEvent) {
    event.preventDefault();
    void run("apply");
  }

  return (
    <div className="https-settings-page">
      <PageHeader
        eyebrow={t("eyebrow")}
        title={t("title")}
        description={t("description")}
        actions={
          <button
            className="button"
            disabled={busy}
            onClick={() => {
              setError("");
              void load().catch((err) =>
                setError(
                  err instanceof Error
                    ? err.message
                    : t("verifyError"),
                ),
              );
            }}
          >
            {t("verifyNow")}
          </button>
        }
      />

      {error && (
        <p className="form-error" role="alert">
          {error}
        </p>
      )}
      {message && (
        <p className="form-success" role="status">
          {message}
        </p>
      )}

      <div className="security-grid">
        <section className="security-card">
          <h2>{t("currentState")}</h2>
          {!status ? (
            <p>{t("loading")}</p>
          ) : (
            <>
              <p>
                <strong>
                  {status.configured
                    ? status.local_tls.healthy
                      ? t("localValid")
                      : t("localNeedsAttention")
                    : t("httpOnly")}
                </strong>
              </p>
              <p>{status.message}</p>
              {status.domain && (
                <p>
                  {t("domain")}: <code>{status.domain}</code>
                </p>
              )}
              {status.configured && (
                <>
                  <p>
                    {t("mode")}:{" "}
                    {status.mode === "automatic"
                      ? t("automaticMode")
                      : t("customCertificate")}
                  </p>
                  <p>
                    {t("localHttps")}:{" "}
                    {status.local_tls.healthy
                      ? t("expectedCertificate")
                      : t("notValidated")}
                  </p>
                  <p>
                    {t("publicDns")}: {t("endpointCount", { count: status.dns.a.length + status.dns.aaaa.length })}
                  </p>
                  <p>
                    {t("endpointValidation")}: {endpointLabels[status.endpoint_validation.status]}
                  </p>
                  <p>{status.endpoint_validation.message}</p>
                  <p>{t("trust")}: {trustLabel(status.trust)}</p>
                  {status.trust && <p>{status.trust.message}</p>}
                </>
              )}
              {status.applied_at && (
                <p>{t("appliedAt")}: {formatDate(status.applied_at, locale)}</p>
              )}
              {status.last_validated_at && (
                <p>{t("lastValidated")}: {formatDate(status.last_validated_at, locale)}</p>
              )}
              {status.certificate && (
                <>
                  <p>{t("issuer")}: {status.certificate.issuer}</p>
                  <p>
                    {t("validFrom")}: {formatDate(status.certificate.valid_from, locale)} {t("until")}{" "}
                    {formatDate(status.certificate.valid_until, locale)}
                  </p>
                  <p>
                    SHA-256: <code>{status.certificate.fingerprint_sha256}</code>
                  </p>
                  <p>
                    SANs:{" "}
                    {status.certificate.san.length > 0
                      ? status.certificate.san.join(", ")
                      : "—"}
                  </p>
                  {status.certificate.chain_length !== undefined && (
                    <p>
                      {t("servedChainCertificates")}: {status.certificate.chain_length}
                    </p>
                  )}
                </>
              )}
              {status.chain && <p>{t("chain")}: {status.chain.message}</p>}
              {status.dns.a.length > 0 && (
                <p>
                  A: <code>{status.dns.a.join(", ")}</code>
                </p>
              )}
              {status.dns.aaaa.length > 0 && (
                <p>
                  AAAA: <code>{status.dns.aaaa.join(", ")}</code>
                </p>
              )}
              {status.endpoint_validation.endpoints.map((endpoint) => (
                <p key={`${endpoint.record_type}-${endpoint.address}`}>
                  {endpoint.record_type} <code>{endpoint.address}</code> · {endpointLabels[endpoint.status]} ·{" "}
                  {endpoint.message}
                </p>
              ))}
            </>
          )}
        </section>

        <section className="security-card">
          <h2>{t("howItWorks")}</h2>
          <p>{t("automaticExplanation")}</p>
          <p>{t("customExplanation")}</p>
          <p>{t("diagnosticExplanation")}</p>
        </section>
      </div>

      <section className="security-card">
        <h2>{t("configure")}</h2>
        <form onSubmit={submit}>
          <div className="settings-form-grid">
            <label>
              {t("mode")}
              <select
                value={mode}
                onChange={(event) => {
                  setMode(event.target.value as "automatic" | "custom");
                  setValidation(null);
                }}
              >
                <option value="automatic">
                  {t("automaticRecommended")}
                </option>
                <option value="custom">{t("customCertificate")}</option>
              </select>
            </label>
            <label>
              {t("publicDomain")}
              <input
                inputMode="url"
                autoComplete="off"
                placeholder={t("domainPlaceholder")}
                maxLength={253}
                value={domain}
                onChange={(event) => {
                  setDomain(event.target.value);
                  setValidation(null);
                }}
                required
              />
            </label>
          </div>

          {mode === "custom" && (
            <>
              <label>
                {t("serverCertificate")}
                <textarea
                  rows={9}
                  autoComplete="off"
                  spellCheck={false}
                  value={serverCertificate}
                  onChange={(event) => {
                    setServerCertificate(event.target.value);
                    setValidation(null);
                  }}
                  placeholder={
                    "-----BEGIN CERTIFICATE-----\n...\n-----END CERTIFICATE-----"
                  }
                  required
                />
              </label>
              <p className="settings-help">{t("serverCertHelp")}</p>

              <label>
                {t("intermediateChain")}
                <textarea
                  rows={9}
                  autoComplete="off"
                  spellCheck={false}
                  value={intermediateChain}
                  onChange={(event) => {
                    setIntermediateChain(event.target.value);
                    setValidation(null);
                  }}
                  placeholder={
                    "-----BEGIN CERTIFICATE-----\n...\n-----END CERTIFICATE-----"
                  }
                />
              </label>
              <p className="settings-help">{t("chainHelp")}</p>

              <label>
                {t("privateKey")}
                <textarea
                  rows={9}
                  autoComplete="off"
                  spellCheck={false}
                  value={privateKey}
                  onChange={(event) => {
                    setPrivateKey(event.target.value);
                    setValidation(null);
                  }}
                  placeholder={
                    "-----BEGIN PRIVATE KEY-----\n...\n-----END PRIVATE KEY-----"
                  }
                  required
                />
              </label>
              <p className="settings-help">{t("privateKeyHelp")}</p>
            </>
          )}

          {validation?.certificate && (
            <div className="settings-help">
              <p>
                {t("validatedCertificate", {issuer: validation.certificate.issuer, date: formatDate(validation.certificate.valid_until, locale)})}
              </p>
              {validation.chain && <p>{validation.chain.message}</p>}
              {validation.trust && <p>{validation.trust.message}</p>}
            </div>
          )}

          <div className="security-actions">
            <button
              className="button"
              type="button"
              disabled={busy}
              onClick={() => void run("validate")}
            >
              {busy ? t("validating") : t("validate")}
            </button>
            <button className="button primary" disabled={busy}>
              {busy ? t("applying") : t("apply")}
            </button>
          </div>
        </form>
      </section>

      <IdentityProof />
    </div>
  );
}

frontend/app/settings/layout.tsx.source:
"use client";

import { usePathname, useRouter } from "next/navigation";
import { useTranslations } from "next-intl";
import { useEffect, useMemo, useRef, useState } from "react";
import { PageContainer, PageHeader } from "@/components/aven";
import { Alert, Button, Skeleton, Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui";
import { api } from "@/lib/api";
import {
  isAdminOnlySettingsPath,
  isSettingsTabActive,
  settingsTabsForRole,
} from "@/lib/settings-navigation.mjs";
import styles from "./settings-layout.module.css";

type CurrentUser = { role: string };

export default function SettingsLayout({ children }: { children: React.ReactNode }) {
  const t = useTranslations("settings");
  const path = usePathname();
  const router = useRouter();
  const navigationViewportRef = useRef<HTMLDivElement | null>(null);
  const [role, setRole] = useState("");
  const [error, setError] = useState("");
  const [retry, setRetry] = useState(0);

  useEffect(() => {
    let active = true;
    setError("");
    api<CurrentUser>("/auth/me")
      .then((user) => {
        if (active) setRole(user.role);
      })
      .catch((err) => {
        if (active) setError(err instanceof Error ? err.message : "ERR_SETTINGS_PERMISSIONS");
      });
    return () => {
      active = false;
    };
  }, [retry]);

  const navigationLabels: Record<string, string> = {
    appearance: t("navigation.appearance"),
    accounts: t("navigation.accounts"),
    policies: t("navigation.policies"),
    security: t("navigation.security"),
    sessions: t("navigation.sessions"),
    users: t("navigation.users"),
    audit: t("navigation.audit"),
    https: t("navigation.https"),
    pricing: t("navigation.pricing"),
    billingProfiles: t("navigation.billingProfiles"),
    usageCosts: t("navigation.usageCosts"),
    retention: t("navigation.retention"),
  };
  const tabs = useMemo(() => settingsTabsForRole(role), [role]);
  const activeTab = useMemo(
    () => tabs.find((tab) => isSettingsTabActive(path, tab.href))?.href ?? tabs[0]?.href ?? path,
    [path, tabs],
  );

  useEffect(() => {
    const activeTabElement = navigationViewportRef.current?.querySelector<HTMLElement>(
      '[role="tab"][aria-selected="true"]',
    );
    activeTabElement?.scrollIntoView({ block: "nearest", inline: "nearest" });
  }, [activeTab]);

  if (error) {
    return (
      <PageContainer width="full" className={styles.statePage}>
        <PageHeader
          title={t("title")}
          description={t("description")}
        />
        <Alert
          variant="danger"
          title={t("errors.loading")}
          description={error === "ERR_SETTINGS_PERMISSIONS" ? t("errors.permissions") : error}
          actions={
            <Button variant="outline" onClick={() => setRetry((value) => value + 1)}>
              {t("retry")}
            </Button>
          }
        />
      </PageContainer>
    );
  }

  if (!role) {
    return (
      <PageContainer
        width="full"
        className={styles.statePage}
        aria-busy="true"
        aria-label={t("loading")}
      >
        <Skeleton className={styles.headerSkeleton} />
        <Skeleton className={styles.navigationSkeleton} />
        <Skeleton className={styles.contentSkeleton} />
      </PageContainer>
    );
  }

  const adminOnly = isAdminOnlySettingsPath(path);

  return (
    <PageContainer width="full" className={styles.page}>
      <Tabs
        value={activeTab}
        defaultValue={activeTab}
        onValueChange={(href) => {
          if (href !== path) router.push(href);
        }}
      >
        <div ref={navigationViewportRef} className={styles.navigationViewport}>
          <TabsList className={styles.tabs} aria-label={t("navigation.ariaLabel")}>
            {tabs.map((tab) => (
              <TabsTrigger key={tab.href} value={tab.href}>
                {navigationLabels[tab.labelKey] ?? tab.labelKey}
              </TabsTrigger>
            ))}
          </TabsList>
        </div>
        <TabsContent value={activeTab} className={styles.content}>
          {adminOnly && role !== "admin" ? (
            <Alert
              variant="warning"
              title={t("restricted.title")}
              description={t("restricted.description")}
            />
          ) : (
            children
          )}
        </TabsContent>
      </Tabs>
    </PageContainer>
  );
}

frontend/app/settings/opportunities/page.source:
"use client";

import { useEffect, useMemo, useState } from "react";
import { useLocale, useTranslations } from "next-intl";
import { AlertTriangle, Eye, Save } from "lucide-react";
import { PageHeader, Section } from "@/components/aven";
import { Alert, Button, Card, Input, Select, Switch } from "@/components/ui";
import { api, ApiError, formatDate } from "@/lib/api";
import { iconDefaults } from "@/lib/iconography";
import styles from "./page.module.css";

type CycleMode = "CALENDAR_MONTH" | "FIXED_DAYS";

type CycleSummary = {
  id: string;
  label: string;
  period_start: string;
  period_end: string;
  status: string;
  timezone: string;
  policy_version: number | null;
};

type Maintenance = {
  last_retention_run_at: string | null;
  last_cycle_close_check_at: string | null;
  last_observation_cleanup_at: string | null;
};

type OpportunityPolicy = {
  id: string;
  cycle_mode: CycleMode;
  cycle_length_days: number;
  cycle_timezone: string;
  cycle_anchor_date: string | null;
  automatic_cycle_close_enabled: boolean;
  treated_archive_enabled: boolean;
  treated_archive_days: number;
  rejected_archive_enabled: boolean;
  rejected_archive_days: number;
  resolved_external_archive_enabled: boolean;
  resolved_external_archive_days: number;
  open_archive_enabled: boolean;
  open_archive_days: number;
  observation_retention_days: number;
  enabled: boolean;
  version: number;
  updated_at: string;
  updated_by: string | null;
  current_cycle: CycleSummary | null;
  next_cycle_start: string | null;
  maintenance: Maintenance;
};

type Preview = {
  treated_eligible: number;
  rejected_eligible: number;
  resolved_externally_eligible: number;
  open_eligible: number;
  observations_eligible_for_purge: number;
  overdue_cycles_awaiting_close: number;
  current_cycle: CycleSummary | null;
  warnings: string[];
};

function editable(policy: OpportunityPolicy) {
  return {
    cycle_mode: policy.cycle_mode,
    cycle_length_days: policy.cycle_length_days,
    cycle_timezone: policy.cycle_timezone,
    cycle_anchor_date: policy.cycle_anchor_date,
    automatic_cycle_close_enabled: policy.automatic_cycle_close_enabled,
    treated_archive_enabled: policy.treated_archive_enabled,
    treated_archive_days: policy.treated_archive_days,
    rejected_archive_enabled: policy.rejected_archive_enabled,
    rejected_archive_days: policy.rejected_archive_days,
    resolved_external_archive_enabled: policy.resolved_external_archive_enabled,
    resolved_external_archive_days: policy.resolved_external_archive_days,
    open_archive_enabled: policy.open_archive_enabled,
    open_archive_days: policy.open_archive_days,
    observation_retention_days: policy.observation_retention_days,
    enabled: policy.enabled,
  };
}

export default function OpportunityPolicyPage() {
  const locale = useLocale();
  const t = useTranslations("settings.opportunities");
  const [policy, setPolicy] = useState<OpportunityPolicy | null>(null);
  const [initial, setInitial] = useState<OpportunityPolicy | null>(null);
  const [preview, setPreview] = useState<Preview | null>(null);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [message, setMessage] = useState("");

  useEffect(() => {
    let active = true;
    api<OpportunityPolicy>("/settings/opportunity-policy")
      .then((data) => {
        if (!active) return;
        setPolicy(data);
        setInitial(data);
      })
      .catch((err) => {
        if (active) setError(err instanceof Error ? err.message : "ERR_OPP_POLICY_LOAD");
      });
    return () => { active = false; };
  }, []);

  const reductionWarning = useMemo(() => {
    if (!policy || !initial) return false;
    return (
      policy.observation_retention_days < initial.observation_retention_days ||
      policy.treated_archive_days < initial.treated_archive_days ||
      policy.rejected_archive_days < initial.rejected_archive_days ||
      policy.resolved_external_archive_days < initial.resolved_external_archive_days ||
      (policy.open_archive_enabled && policy.open_archive_days < initial.open_archive_days)
    );
  }, [policy, initial]);

  function patch(changes: Partial<OpportunityPolicy>) {
    setPolicy((current) => current ? { ...current, ...changes } : current);
    setPreview(null);
    setMessage("");
  }

  async function runPreview() {
    if (!policy) return;
    setBusy(true);
    setError("");
    try {
      setPreview(
        await api<Preview>("/settings/opportunity-policy/preview", {
          method: "POST",
          body: JSON.stringify(editable(policy)),
        }),
      );
    } catch (err) {
      setError(err instanceof Error ? err.message : "ERR_OPP_POLICY_PREVIEW");
    } finally {
      setBusy(false);
    }
  }

  async function save() {
    if (!policy) return;
    setBusy(true);
    setError("");
    setMessage("");
    try {
      const saved = await api<OpportunityPolicy>("/settings/opportunity-policy", {
        method: "PUT",
        body: JSON.stringify({ ...editable(policy), expected_version: policy.version }),
      });
      setPolicy(saved);
      setInitial(saved);
      setPreview(null);
      setMessage("OPP_POLICY_UPDATED");
    } catch (err) {
      if (err instanceof ApiError && err.status === 409) {
        setError(
          "ERR_OPP_POLICY_CONFLICT",
        );
      } else {
        setError(err instanceof Error ? err.message : "ERR_OPP_POLICY_SAVE");
      }
    } finally {
      setBusy(false);
    }
  }

  if (!policy) {
    return (
      <div className={styles.page}>
        <PageHeader
          title={t("title")}
          description={t("loadingDescription")}
          metadata={<span>{t("metadata")}</span>}
        />
        {error && <Alert variant="danger" title={t("loadErrorTitle")} description={error === "ERR_OPP_POLICY_LOAD" ? t("errors.load") : error === "ERR_OPP_POLICY_PREVIEW" ? t("errors.preview") : error === "ERR_OPP_POLICY_SAVE" ? t("errors.save") : error === "ERR_OPP_POLICY_CONFLICT" ? t("errors.conflict") : error} />}
      </div>
    );
  }

  const cycle = policy.current_cycle;

  return (
    <div className={styles.page}>
      <PageHeader
        title={t("title")}
        description={t("description")}
        metadata={<span>{t("metadata")}</span>}
      />

      {error && <Alert variant="danger" title={t("updateErrorTitle")} description={error === "ERR_OPP_POLICY_LOAD" ? t("errors.load") : error === "ERR_OPP_POLICY_PREVIEW" ? t("errors.preview") : error === "ERR_OPP_POLICY_SAVE" ? t("errors.save") : error === "ERR_OPP_POLICY_CONFLICT" ? t("errors.conflict") : error} />}
      {message && <Alert variant="success" title={message === "OPP_POLICY_UPDATED" ? t("updated") : message} />}

      <section className={styles.statusGrid} aria-label={t("summaryAria")}>
        <PolicyStatus label={t("version")} value={String(policy.version)} detail={t("updatedAt", {date: formatDate(policy.updated_at, locale)})} />
        <PolicyStatus
          label={t("currentCycle")}
          value={cycle?.label || t("notCreated")}
          detail={cycle ? `${formatDate(cycle.period_start, locale)} → ${formatDate(cycle.period_end, locale)}` : t("willCreate")}
        />
        <PolicyStatus
          label={t("nextClosure")}
          value={policy.next_cycle_start ? formatDate(policy.next_cycle_start, locale) : "—"}
          detail={policy.automatic_cycle_close_enabled ? t("automatic") : t("manualClosure")}
        />
      </section>

      <Section
        appearance="card"
        title={t("cyclesTitle")}
        description={t("cyclesDescription")}
        actions={(
          <Switch
            aria-label={t("automaticClosureAria")}
            checked={policy.automatic_cycle_close_enabled}
            onCheckedChange={(checked) => patch({ automatic_cycle_close_enabled: checked })}
          />
        )}
      >
        <div className={styles.formGrid}>
          <Select
            label={t("cycleMode")}
            value={policy.cycle_mode}
            onChange={(event) => patch({ cycle_mode: event.target.value as CycleMode })}
            options={[
              { value: "CALENDAR_MONTH", label: t("calendarMonth") },
              { value: "FIXED_DAYS", label: t("fixedDays") },
            ]}
          />
          <Input
            label={t("timezone")}
            value={policy.cycle_timezone}
            list="cycle-timezones"
            onChange={(event) => patch({ cycle_timezone: event.target.value })}
          />
          <datalist id="cycle-timezones">
            <option value="UTC" />
            <option value="America/Sao_Paulo" />
          </datalist>
          {policy.cycle_mode === "FIXED_DAYS" && (
            <>
              <Input
                label={t("cycleLength")}
                type="number"
                min={7}
                max={365}
                value={policy.cycle_length_days}
                onChange={(event) => patch({ cycle_length_days: Number(event.target.value) })}
              />
              <Input
                label={t("anchorDate")}
                type="date"
                value={policy.cycle_anchor_date || ""}
                onChange={(event) => patch({ cycle_anchor_date: event.target.value || null })}
              />
            </>
          )}
        </div>

        {cycle && (
          <Alert
            variant="info"
            title={t("preservedPeriod")}
            description={(
              <span>
                {t("periodFrom")} <strong>{formatDate(cycle.period_start, locale)}</strong> {t("periodTo")}{" "}
                <strong>{formatDate(cycle.period_end, locale)}</strong>{t("periodChanges")}
              </span>
            )}
          />
        )}
      </Section>

      <Section
        appearance="card"
        title={t("automaticArchive")}
        description={t("archiveDescription")}
        actions={(
          <Switch
            aria-label={t("enableAutomations")}
            checked={policy.enabled}
            onCheckedChange={(checked) => patch({ enabled: checked })}
          />
        )}
      >
        <div className={styles.retentionTable}>
          <RetentionRow
            label={t("treated")}
            detail={t("treatedDetail")}
            enabled={policy.treated_archive_enabled}
            days={policy.treated_archive_days}
            onEnabled={(value) => patch({ treated_archive_enabled: value })}
            onDays={(value) => patch({ treated_archive_days: value })}
          />
          <RetentionRow
            label={t("rejected")}
            detail={t("rejectedDetail")}
            enabled={policy.rejected_archive_enabled}
            days={policy.rejected_archive_days}
            onEnabled={(value) => patch({ rejected_archive_enabled: value })}
            onDays={(value) => patch({ rejected_archive_days: value })}
          />
          <RetentionRow
            label={t("resolvedExternally")}
            detail={t("resolvedExternallyDetail")}
            enabled={policy.resolved_external_archive_enabled}
            days={policy.resolved_external_archive_days}
            onEnabled={(value) => patch({ resolved_external_archive_enabled: value })}
            onDays={(value) => patch({ resolved_external_archive_days: value })}
          />
          <RetentionRow
            label={t("open")}
            detail={t("openDetail")}
            enabled={policy.open_archive_enabled}
            days={policy.open_archive_days}
            onEnabled={(value) => patch({ open_archive_enabled: value })}
            onDays={(value) => patch({ open_archive_days: value })}
          />
        </div>
      </Section>

      <Section appearance="card" title={t("observationDetails")}>
        <div className={styles.singleField}>
          <Input
            label={t("retentionDays")}
            type="number"
            min={policy.cycle_mode === "CALENDAR_MONTH" ? 31 : Math.max(30, policy.cycle_length_days)}
            max={3650}
            value={policy.observation_retention_days}
            onChange={(event) => patch({ observation_retention_days: Number(event.target.value) })}
            helperText={t("retentionHelp")}
          />
        </div>
      </Section>

      {reductionWarning && (
        <Alert
          variant="warning"
          icon={<AlertTriangle {...iconDefaults} />}
          title={t("retentionReduction")}
          description={t("retentionWarning")}
        />
      )}

      <Section
        appearance="card"
        title={t("impactTitle")}
        description={t("impactDescription")}
        actions={(
          <div className={styles.actions}>
            <Button
              variant="secondary"
              leadingIcon={<Eye {...iconDefaults} />}
              onClick={() => void runPreview()}
              disabled={busy}
            >
              {t("previewAction")}
            </Button>
            <Button
              variant="primary"
              leadingIcon={<Save {...iconDefaults} />}
              onClick={() => void save()}
              loading={busy}
            >
              {t("savePolicy")}
            </Button>
          </div>
        )}
      >
        {preview ? (
          <div className={styles.preview}>
            <div className={styles.previewGrid}>
              <Metric label={t("treatedEligible")} value={preview.treated_eligible} />
              <Metric label={t("rejectedEligible")} value={preview.rejected_eligible} />
              <Metric label={t("resolvedEligible")} value={preview.resolved_externally_eligible} />
              <Metric label={t("openEligible")} value={preview.open_eligible} />
              <Metric label={t("observationsEligible")} value={preview.observations_eligible_for_purge} />
              <Metric label={t("overdueCycles")} value={preview.overdue_cycles_awaiting_close} />
            </div>
            {preview.warnings.map((warning) => (
              <Alert key={warning} variant="warning" description={warning} />
            ))}
          </div>
        ) : (
          <p className={styles.secondaryText}>{t("previewHelp")}</p>
        )}
      </Section>

      <Section appearance="card" title={t("lastRuns")}>
        <div className={styles.maintenanceGrid}>
          <MaintenanceItem label={t("retention")} value={formatDate(policy.maintenance.last_retention_run_at, locale)} />
          <MaintenanceItem label={t("automaticClosure")} value={formatDate(policy.maintenance.last_cycle_close_check_at, locale)} />
          <MaintenanceItem label={t("observationCleanup")} value={formatDate(policy.maintenance.last_observation_cleanup_at, locale)} />
        </div>
      </Section>
    </div>
  );
}

function PolicyStatus({ label, value, detail }: { label: string; value: string; detail: string }) {
  return (
    <Card className={styles.statusCard}>
      <span className={styles.kicker}>{label}</span>
      <strong className={styles.statusValue}>{value}</strong>
      <span className={styles.statusMeta}>{detail}</span>
    </Card>
  );
}

function RetentionRow({
  label,
  detail,
  enabled,
  days,
  onEnabled,
  onDays,
}: {
  label: string;
  detail: string;
  enabled: boolean;
  days: number;
  onEnabled: (value: boolean) => void;
  onDays: (value: number) => void;
}) {
  const t = useTranslations("settings.opportunities");
  return (
    <div className={styles.retentionRow}>
      <div className={styles.retentionCopy}>
        <strong>{label}</strong>
        <span>{detail}</span>
      </div>
      <Switch
        aria-label={t("enableArchive", {label})}
        checked={enabled}
        onCheckedChange={onEnabled}
      />
      <div className={styles.afterDays}>
        <span>{t("after")}</span>
        <div className={styles.daysControl}>
          <Input
            aria-label={t("daysFor", {label})}
            type="number"
            min={1}
            max={3650}
            value={days}
            disabled={!enabled}
            onChange={(event) => onDays(Number(event.target.value))}
          />
        </div>
        <span>{t("days")}</span>
      </div>
    </div>
  );
}

function Metric({ label, value }: { label: string; value: number }) {
  return (
    <div className={styles.metric}>
      <strong>{value.toLocaleString(useLocale())}</strong>
      <span>{label}</span>
    </div>
  );
}

function MaintenanceItem({ label, value }: { label: string; value: string }) {
  return (
    <div className={styles.maintenanceItem}>
      <span>{label}</span>
      <strong>{value}</strong>
    </div>
  );
}

frontend/app/settings/policies/page.tsx.source:
"use client";

import { useEffect, useState, type ReactNode } from "react";
import { useTranslations } from "next-intl";
import { RotateCcw, Save, SlidersHorizontal } from "lucide-react";
import { PageHeader } from "@/components/aven";
import {
  Alert,
  Badge,
  Button,
  Card,
  Checkbox,
  EmptyState,
  Input,
  Select,
  Switch,
  Textarea,
} from "@/components/ui";
import { api } from "@/lib/api";
import { providerLabel } from "@/lib/cloud.mjs";
import { iconDefaults } from "@/lib/iconography";
import { canManagePolicies } from "@/lib/settings-navigation.mjs";
import type { CloudAccount, Policy, ProviderCapabilities } from "@/lib/types";
import styles from "./page.module.css";

type CurrentUser = { role: string };
type AwsPolicyAccount = CloudAccount & { aws_configuration: NonNullable<CloudAccount["aws_configuration"]> };

type SegmentedOption = {
  value: string;
  label: ReactNode;
  disabled?: boolean;
};

export default function PoliciesPage() {
  const t = useTranslations("settings.policies");
  const [provider, setProvider] = useState("aws");
  const [scope, setScope] = useState<"global" | "account">("global");
  const [accountId, setAccountId] = useState<number | null>(null);
  const [accounts, setAccounts] = useState<AwsPolicyAccount[]>([]);
  const [capabilities, setCapabilities] = useState<ProviderCapabilities[]>([]);
  const [policies, setPolicies] = useState<Policy[]>([]);
  const [role, setRole] = useState("");
  const [message, setMessage] = useState<{ kind: "updated" | "reset"; name: string } | null>(null);
  const [error, setError] = useState("");
  const canManage = canManagePolicies(role);
  const providerCapabilities = capabilities.find((item) => item.provider === provider);
  const availableProviders = capabilities.filter((item) => item.registration);

  useEffect(() => {
    let active = true;
    Promise.all([
      api<CloudAccount[]>("/cloud-accounts"),
      api<ProviderCapabilities[]>("/cloud-accounts/capabilities"),
      api<CurrentUser>("/auth/me"),
    ])
      .then(([data, providerCapabilities, user]) => {
        if (!active) return;
        const awsAccounts = data.filter(
          (account): account is AwsPolicyAccount =>
            account.provider === "aws" && account.aws_configuration !== null,
        );
        setAccounts(awsAccounts);
        setCapabilities(providerCapabilities);
        setRole(user.role);
        if (awsAccounts[0]) setAccountId(awsAccounts[0].aws_configuration.id);
      })
      .catch((err) => {
        if (active) setError(err instanceof Error ? err.message : "ERR_POLICIES_SETTINGS_LOAD");
      });
    return () => { active = false; };
  }, []);

  useEffect(() => {
    if (!providerCapabilities) return;
    if (!providerCapabilities.finops_policies) {
      setPolicies([]);
      setError("");
      return;
    }
    if (provider !== "aws") {
      setPolicies([]);
      return;
    }
    if (scope === "account" && !accountId) return;
    setError("");
    api<Policy[]>(scope === "global" ? "/policies/global" : `/policies/accounts/${accountId}`)
      .then(setPolicies)
      .catch((err) => setError(err instanceof Error ? err.message : "ERR_POLICIES_LOAD"));
  }, [provider, providerCapabilities, scope, accountId]);

  async function refresh() {
    if (!providerCapabilities?.finops_policies || provider !== "aws") return;
    setPolicies(
      await api<Policy[]>(
        scope === "global" ? "/policies/global" : `/policies/accounts/${accountId}`,
      ),
    );
  }

  return (
    <div className={styles.page}>
      <PageHeader
        title={t("title")}
        description={t("description")}
        metadata={<span>{t("metadata")}</span>}
      />

      {error && <Alert variant="danger" title={t("loadError")} description={error === "ERR_POLICIES_SETTINGS_LOAD" ? t("settingsLoadFailed") : error === "ERR_POLICIES_LOAD" ? t("loadError") : error} />}
      {message && <Alert variant="success" title={message.kind === "updated" ? t("updated", {name: message.name}) : t("resetSuccess", {name: message.name})} />}

      <div className={styles.scopeStack}>
        <div className={styles.scopeRow}>
          <SegmentedButtons
            label={t("policyCloud")}
            value={provider}
            options={availableProviders.map((item) => ({ value: item.provider, label: item.label }))}
            onValueChange={(nextProvider) => {
              setProvider(nextProvider);
              setScope("global");
              setMessage(null);
            }}
          />
          <p className={styles.scopeDescription}>
            {t("iamNote")}
          </p>
        </div>

        {providerCapabilities?.finops_policies && (
          <div className={styles.scopeRow}>
            <SegmentedButtons
              label={t("scope")}
              value={scope}
              options={[
                { value: "global", label: t("globalAws") },
                { value: "account", label: t("awsAccountScope"), disabled: !accounts.length },
              ]}
              onValueChange={(nextScope) => setScope(nextScope as "global" | "account")}
            />
            {scope === "account" && (
              <div className={styles.accountSelect}>
                <Select
                  aria-label={t("awsAccount")}
                  value={accountId === null ? "" : String(accountId)}
                  onChange={(event) => setAccountId(Number(event.target.value))}
                  options={accounts.map((account) => ({
                    value: String(account.aws_configuration.id),
                    label: `${account.name} · ${account.native_account_id}`,
                  }))}
                />
              </div>
            )}
            <p className={styles.scopeDescription}>
              {scope === "global"
                ? t("globalScopeDescription")
                : t("accountScopeDescription")}
            </p>
          </div>
        )}
      </div>

      {providerCapabilities && !providerCapabilities.finops_policies ? (
        <EmptyState
          icon={<SlidersHorizontal {...iconDefaults} />}
          title={t("unavailableTitle", {provider: providerCapabilities.label})}
          description={t("unavailableDescription")}
        />
      ) : (
        <section className={styles.policiesList} aria-label={t("listLabel")}>
          {policies.map((policy) => (
            <PolicyCard
              key={`${scope}-${accountId}-${policy.rule_key}-${policy.override_fields.join(".")}`}
              policy={policy}
              scope={scope}
              accountId={accountId}
              canManage={canManage}
              onSaved={async (kind, name) => {
                setMessage({kind, name});
                await refresh();
              }}
            />
          ))}
        </section>
      )}
    </div>
  );
}

function SegmentedButtons({
  label,
  value,
  options,
  onValueChange,
}: {
  label: string;
  value: string;
  options: SegmentedOption[];
  onValueChange: (value: string) => void;
}) {
  return (
    <div className={styles.segmentedGroup} role="group" aria-label={label}>
      {options.map((option) => {
        const selected = option.value === value;
        return (
          <Button
            key={option.value}
            size="sm"
            variant={selected ? "secondary" : "ghost"}
            aria-pressed={selected}
            disabled={option.disabled}
            onClick={() => onValueChange(option.value)}
          >
            {option.label}
          </Button>
        );
      })}
    </div>
  );
}

function PolicyCard({ policy, scope, accountId, canManage, onSaved }: { policy: Policy; scope: "global" | "account"; accountId: number | null; canManage: boolean; onSaved: (kind: "updated" | "reset", name: string) => Promise<void> }) {
  const t = useTranslations("settings.policies");
  const fieldLabels: Record<string, string> = {
    minimum_age_days: t("fields.minimumAgeDays"),
    minimum_monthly_savings_usd: t("fields.minimumMonthlySavingsUsd"),
    monthly_price_per_gb: t("fields.monthlyPricePerGb"),
    excluded_tag_keys: t("fields.excludedTagKeys"),
    monthly_cost_usd: t("fields.monthlyCostUsd"),
    retention_days: t("fields.retentionDays"),
    preserve_last_per_volume: t("fields.preserveLastPerVolume"),
    preserve_ami_snapshots: t("fields.preserveAmiSnapshots"),
    minimum_stopped_days: t("fields.minimumStoppedDays"),
    include_unknown_stop_time: t("fields.includeUnknownStopTime"),
    timezone: t("fields.timezone"),
    business_days: t("fields.businessDays"),
    business_hours_start: t("fields.businessHoursStart"),
    business_hours_end: t("fields.businessHoursEnd"),
    environment_tag_keys: t("fields.environmentTagKeys"),
    nonproduction_values: t("fields.nonproductionValues"),
    lookback_days: t("fields.lookbackDays"),
    maximum_requests: t("fields.maximumRequests"),
    maximum_average_cpu_percent: t("fields.maximumAverageCpuPercent"),
    maximum_connections: t("fields.maximumConnections"),
    required_tags: t("fields.requiredTags"),
    resource_types: t("fields.resourceTypes"),
    baseline_days: t("fields.baselineDays"),
    comparison_days: t("fields.comparisonDays"),
    minimum_growth_percent: t("fields.minimumGrowthPercent"),
    minimum_delta_usd: t("fields.minimumDeltaUsd"),
    minimum_current_spend_usd: t("fields.minimumCurrentSpendUsd"),
  };
  const [enabled, setEnabled] = useState(policy.enabled);
  const [values, setValues] = useState<Record<string, unknown>>({ ...policy.config });
  const [overrides, setOverrides] = useState<Set<string>>(new Set(policy.override_fields));
  const [open, setOpen] = useState(false);
  const [busy, setBusy] = useState(false);

  function changeValue(key: string, original: unknown, raw: unknown) {
    if (!canManage) return;
    let next: unknown = raw;
    if (typeof original === "number") next = Number(raw);
    if (Array.isArray(original)) next = String(raw).split(",").map((item) => item.trim()).filter(Boolean);
    setValues((current) => ({ ...current, [key]: next }));
  }

  async function save() {
    if (!canManage) return;
    setBusy(true);
    try {
      const config = scope === "global" ? values : Object.fromEntries(Object.entries(values).filter(([key]) => overrides.has(key)));
      const enabledValue = scope === "global" || overrides.has("enabled") ? enabled : null;
      const path = scope === "global" ? `/policies/global/${policy.rule_key}` : `/policies/accounts/${accountId}/${policy.rule_key}`;
      await api(path, { method: "PUT", body: JSON.stringify({ enabled: enabledValue, config }) });
      await onSaved("updated", policy.name);
    } finally { setBusy(false); }
  }

  async function reset() {
    if (!canManage || scope !== "account") return;
    setBusy(true);
    try {
      await api(`/policies/accounts/${accountId}/${policy.rule_key}`, { method: "DELETE" });
      await onSaved("reset", policy.name);
    } finally { setBusy(false); }
  }

  return (
    <Card className={`${styles.policyCard} ${policy.implemented ? "" : styles.plannedCard}`}>
      <div className={styles.policySummary}>
        <span className={styles.policyIcon}><SlidersHorizontal {...iconDefaults} /></span>
        <div className={styles.policyCopy}>
          <div className={styles.policyTitleLine}>
            <h3 className={styles.policyTitle}>{policy.name}</h3>
            <Badge variant="info">{providerLabel(policy.provider)}</Badge>
            {!policy.implemented && <Badge variant="warning">{t("planned")}</Badge>}
            {scope === "account" && policy.inherited && <Badge variant="neutral">{t("inherited")}</Badge>}
          </div>
          <p className={styles.policyDescription}>{policy.description}</p>
        </div>
        <div className={styles.policySummaryActions}>
          <Switch
            aria-label={canManage ? t("enablePolicy", {name: policy.name}) : t("statusPolicy", {name: policy.name})}
            checked={enabled}
            onCheckedChange={(checked) => {
              if (!canManage) return;
              setEnabled(checked);
              if (scope === "account") setOverrides(new Set([...overrides, "enabled"]));
            }}
            disabled={!policy.implemented || !canManage}
          />
          <Button variant="ghost" size="sm" onClick={() => setOpen(!open)} aria-expanded={open}>
            {open ? t("close") : canManage ? t("configure") : t("view")}
          </Button>
        </div>
      </div>

      {open && (
        <div className={styles.policyEditor}>
          <div className={styles.policyFields}>
            {Object.entries(values).map(([key, value]) => {
              const fieldDisabled = !canManage || (scope === "account" && !overrides.has(key));
              return (
                <div className={styles.policyField} key={key}>
                  {scope === "account" && (
                    <Checkbox
                      aria-label={t("override", {field: fieldLabels[key] ?? humanize(key)})}
                      checked={overrides.has(key)}
                      disabled={!canManage}
                      onChange={(event) => {
                        if (!canManage) return;
                        const next = new Set(overrides);
                        event.target.checked ? next.add(key) : next.delete(key);
                        setOverrides(next);
                      }}
                    />
                  )}
                  <div className={styles.policyFieldControl}>
                    {renderInput(key, value, (raw) => changeValue(key, value, raw), fieldDisabled, fieldLabels, {yes: t("yes"), no: t("no"), invalidJson: t("invalidJson")})}
                  </div>
                </div>
              );
            })}
          </div>

          {canManage && (
            <div className={styles.policyActions}>
              {scope === "account" && (
                <Button
                  variant="ghost"
                  leadingIcon={<RotateCcw {...iconDefaults} />}
                  onClick={() => void reset()}
                  disabled={busy}
                >
                  {t("restoreInheritance")}
                </Button>
              )}
              <Button
                variant="primary"
                leadingIcon={<Save {...iconDefaults} />}
                onClick={() => void save()}
                loading={busy}
                disabled={!policy.implemented}
              >
                {t("savePolicy")}
              </Button>
            </div>
          )}
        </div>
      )}
    </Card>
  );
}

function renderInput(key: string, value: unknown, onChange: (value: unknown) => void, disabled: boolean, fieldLabels: Record<string, string>, words: {yes: string; no: string; invalidJson: string}) {
  const label = fieldLabels[key] ?? humanize(key);
  if (typeof value === "boolean") {
    return (
      <Select
        label={label}
        value={String(value)}
        onChange={(event) => onChange(event.target.value === "true")}
        disabled={disabled}
        options={[
          { value: "true", label: words.yes },
          { value: "false", label: words.no },
        ]}
      />
    );
  }
  if (typeof value === "number") {
    return <Input label={label} type="number" value={value} onChange={(event) => onChange(event.target.value)} disabled={disabled} />;
  }
  if (Array.isArray(value)) {
    return <Input label={label} value={value.join(", ")} onChange={(event) => onChange(event.target.value)} disabled={disabled} />;
  }
  if (typeof value === "object" && value !== null) {
    return <ObjectEditor label={label} value={value as Record<string, unknown>} onChange={onChange} disabled={disabled} invalidJson={words.invalidJson} />;
  }
  return <Input label={label} value={String(value ?? "")} onChange={(event) => onChange(event.target.value)} disabled={disabled} />;
}

function ObjectEditor({ label, value, onChange, disabled, invalidJson }: { label: string; value: Record<string, unknown>; onChange: (value: Record<string, unknown>) => void; disabled: boolean; invalidJson: string }) {
  const [text, setText] = useState(JSON.stringify(value, null, 2));
  const [invalid, setInvalid] = useState(false);
  return (
    <Textarea
      label={label}
      rows={4}
      value={text}
      disabled={disabled}
      error={invalid ? invalidJson : undefined}
      onChange={(event) => {
        const next = event.target.value;
        setText(next);
        try {
          const parsed = JSON.parse(next);
          if (!parsed || Array.isArray(parsed) || typeof parsed !== "object") throw new Error();
          setInvalid(false);
          onChange(parsed);
        } catch {
          setInvalid(true);
        }
      }}
    />
  );
}

function humanize(value: string) {
  return value.replaceAll("_", " ");
}

frontend/app/settings/pricing/oci/page.t.source:
"use client";

import { useCallback, useEffect, useMemo, useState } from "react";
import { useLocale, useTranslations } from "next-intl";
import {formatLocaleDateTime} from "@/i18n/formatters.mjs";
import { Check, History, Pencil, Plus, Search, XCircle } from "lucide-react";
import { PageHeader } from "@/components/page-header";
import { api } from "@/lib/api";
import {
  datetimeLocalToIso,
  formatBrlDecimal,
  normalizeDecimalInput,
  pricingLifecycleStatus,
  pricingStatusLabel,
  sourceLabel,
  toDatetimeLocal,
  unitLabel,
} from "@/lib/pricing.mjs";
import styles from "./pricing.module.css";

type PricingItem = {
  id: string;
  provider: string;
  service: string;
  sku: string;
  description: string;
  unit: string;
  price: string;
  currency: string;
  effective_from: string;
  effective_until: string | null;
  enabled: boolean;
  source: string;
  created_at: string;
  updated_at: string;
};

type PricingList = {
  items: PricingItem[];
  total: number;
  limit: number;
  offset: number;
};

type PricingMeta = {
  provider: string;
  currency: string;
  services: string[];
  units: string[];
  sources: string[];
};

type AuditSnapshot = {
  id?: string;
  price?: string;
  currency?: string;
  description?: string;
  effective_from?: string;
  effective_until?: string | null;
  enabled?: boolean;
  source?: string;
};

type PricingAuditEvent = {
  id: string;
  pricing_item_id: string;
  action: string;
  actor_type: string;
  actor_name: string | null;
  actor_email: string | null;
  reason: string | null;
  before_data: AuditSnapshot | null;
  after_data: AuditSnapshot | null;
  occurred_at: string;
};

type PricingAuditPage = {
  items: PricingAuditEvent[];
  page: number;
  page_size: number;
  total: number;
  total_pages: number;
};

const PAGE_SIZE = 25;
const AUDIT_PAGE_SIZE = 10;

function apiMessage(error: unknown, fallback: string) {
  return error instanceof Error ? error.message : fallback;
}

export default function OciPricingPage() {
  const locale = useLocale();
  const t = useTranslations("settings.ociPricing");
  const statusWords: Record<string, string> = {active:t("statusActive"),inactive:t("statusInactive"),future:t("statusFuture"),expired:t("statusExpired")};
  const sourceWords: Record<string, string> = {IMPORTED_OCI_CALCULATOR:t("sourceImported"),MANUAL:t("sourceManual")};
  const unitWords: Record<string, string> = {OCPU_HOUR:t("unitOcpu"),GB_RAM_HOUR:t("unitRam"),GB_MONTH:t("unitGb"),VPU_GB_MONTH:t("unitVpu"),INSTANCE_HOUR:t("unitInstance")};
  const [items, setItems] = useState<PricingItem[]>([]);
  const [meta, setMeta] = useState<PricingMeta | null>(null);
  const [total, setTotal] = useState(0);
  const [queryDraft, setQueryDraft] = useState("");
  const [query, setQuery] = useState("");
  const [service, setService] = useState("");
  const [status, setStatus] = useState("active");
  const [offset, setOffset] = useState(0);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [message, setMessage] = useState("");
  const [form, setForm] = useState<{ mode: "create" | "edit"; item?: PricingItem } | null>(null);
  const [historyItem, setHistoryItem] = useState<PricingItem | null>(null);
  const [auditItem, setAuditItem] = useState<PricingItem | null>(null);

  const load = useCallback(async () => {
    setLoading(true);
    setError("");
    try {
      const params = new URLSearchParams({
        status,
        limit: String(PAGE_SIZE),
        offset: String(offset),
      });
      if (query) params.set("q", query);
      if (service) params.set("service", service);
      const [data, metadata] = await Promise.all([
        api<PricingList>(`/pricing/oci?${params}`),
        meta ? Promise.resolve(meta) : api<PricingMeta>("/pricing/oci/meta"),
      ]);
      setItems(data.items);
      setTotal(data.total);
      setMeta(metadata);
    } catch (err) {
      setError(apiMessage(err, t("loadFailed")));
    } finally {
      setLoading(false);
    }
  }, [meta, offset, query, service, status]);

  useEffect(() => {
    void load();
  }, [load]);

  function applySearch(event: React.FormEvent) {
    event.preventDefault();
    setOffset(0);
    setQuery(queryDraft.trim());
  }

  async function deactivate(item: PricingItem) {
    const confirmed = window.confirm(
      t("deactivateConfirm"),
    );
    if (!confirmed) return;
    const reason = window.prompt(
      t("reasonPrompt"),
      "",
    )?.trim();
    if (!reason || reason.length < 3) {
      setError(t("reasonTooShort"));
      return;
    }
    setError("");
    setMessage("");
    try {
      await api(`/pricing/oci/${item.id}/deactivate`, {
        method: "POST",
        body: JSON.stringify({ reason }),
      });
      setMessage(t("priceDeactivated", {sku: item.sku}));
      await load();
    } catch (err) {
      setError(apiMessage(err, t("deactivateFailed")));
    }
  }

  const pageNumber = Math.floor(offset / PAGE_SIZE) + 1;
  const pageCount = Math.max(1, Math.ceil(total / PAGE_SIZE));

  return (
    <>
      <PageHeader
        eyebrow={t("eyebrow")}
        title={t("title")}
        description={t("description")}
        actions={
          <button className="button primary" onClick={() => setForm({ mode: "create" })}>
            <Plus size={16} /> {t("newPrice")}
          </button>
        }
      />

      {error && <div className="alert error" role="alert">{error}</div>}
      {message && <div className="alert success"><Check size={17} />{message}</div>}

      <section className={`panel ${styles.filters}`}>
        <form onSubmit={applySearch} className={styles.search}>
          <label>
            <span>{t("search")}</span>
            <div className={styles.searchInput}>
              <Search size={16} />
              <input
                value={queryDraft}
                onChange={(event) => setQueryDraft(event.target.value)}
                placeholder={t("searchPlaceholder")}
              />
            </div>
          </label>
          <button className="button ghost" type="submit">{t("searchButton")}</button>
        </form>
        <label>
          <span>{t("service")}</span>
          <select
            value={service}
            onChange={(event) => {
              setOffset(0);
              setService(event.target.value);
            }}
          >
            <option value="">{t("all")}</option>
            {meta?.services.map((value) => <option key={value} value={value}>{serviceLabel(value)}</option>)}
          </select>
        </label>
        <label>
          <span>{t("status")}</span>
          <select
            value={status}
            onChange={(event) => {
              setOffset(0);
              setStatus(event.target.value);
            }}
          >
            <option value="active">{t("activePlural")}</option>
            <option value="inactive">{t("inactivePlural")}</option>
            <option value="future">{t("futurePlural")}</option>
            <option value="expired">{t("expiredPlural")}</option>
            <option value="all">{t("all")}</option>
          </select>
        </label>
      </section>

      <section className={`panel ${styles.catalog}`}>
        {loading ? (
          <div className={styles.state} role="status">{t("loading")}</div>
        ) : items.length === 0 ? (
          <div className={styles.state}>
            {query || service || status !== "active"
              ? t("noFiltered")
              : t("noResults")}
          </div>
        ) : (
          <div className={styles.tableWrap}>
            <table className={styles.table}>
              <thead>
                <tr>
                  <th>{t("service")}</th>
                  <th>{t("sku")}</th>
                  <th>{t("itemDescription")}</th>
                  <th>{t("unit")}</th>
                  <th>{t("price")}</th>
                  <th>{t("validity")}</th>
                  <th>{t("status")}</th>
                  <th>{t("source")}</th>
                  <th aria-label={t("actions")} />
                </tr>
              </thead>
              <tbody>
                {items.map((item) => {
                  const itemStatus = pricingLifecycleStatus(item);
                  return (
                    <tr key={item.id}>
                      <td>{serviceLabel(item.service)}</td>
                      <td><code>{item.sku}</code></td>
                      <td>{item.description}</td>
                      <td>{unitWords[item.unit] ?? unitLabel(item.unit)}</td>
                      <td>
                        <strong>{formatBrlDecimal(item.price, locale)}</strong>
                        <small>{item.currency}</small>
                      </td>
                      <td>{formatRange(item, locale)}</td>
                      <td><span className={statusClass(itemStatus)}>{statusWords[itemStatus] ?? pricingStatusLabel(itemStatus)}</span></td>
                      <td>{sourceWords[item.source] ?? sourceLabel(item.source)}</td>
                      <td>
                        <div className={styles.rowActions}>
                          <button className="button small ghost" onClick={() => setHistoryItem(item)}>
                            <History size={14} /> {t("versions")}
                          </button>
                          <button className="button small ghost" onClick={() => setAuditItem(item)}>
                            Auditoria
                          </button>
                          {item.enabled && itemStatus !== "expired" && (
                            <>
                              <button className="button small ghost" onClick={() => setForm({ mode: "edit", item })}>
                                <Pencil size={14} /> {t("edit")}
                              </button>
                              <button className="button small ghost" onClick={() => void deactivate(item)}>
                                <XCircle size={14} /> {t("deactivate")}
                              </button>
                            </>
                          )}
                        </div>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}

        <div className={styles.pagination}>
          <span>{t("recordCount", {count: total, page: pageNumber, pages: pageCount})}</span>
          <div>
            <button
              className="button small ghost"
              disabled={offset === 0 || loading}
              onClick={() => setOffset(Math.max(0, offset - PAGE_SIZE))}
            >
              Anterior
            </button>
            <button
              className="button small ghost"
              disabled={offset + PAGE_SIZE >= total || loading}
              onClick={() => setOffset(offset + PAGE_SIZE)}
            >
              Próxima
            </button>
          </div>
        </div>
      </section>

      {form && (
        <PricingForm
          mode={form.mode}
          item={form.item}
          meta={meta}
          onClose={() => setForm(null)}
          onSaved={async (text) => {
            setForm(null);
            setMessage(text);
            setError("");
            await load();
          }}
        />
      )}
      {historyItem && <PricingHistory item={historyItem} onClose={() => setHistoryItem(null)} />}
      {auditItem && <PricingAuditHistory item={auditItem} onClose={() => setAuditItem(null)} />}
    </>
  );
}

function PricingForm({
  mode,
  item,
  meta,
  onClose,
  onSaved,
}: {
  mode: "create" | "edit";
  item?: PricingItem;
  meta: PricingMeta | null;
  onClose: () => void;
  onSaved: (message: string) => Promise<void>;
}) {
  const locale = useLocale();
  const t = useTranslations("settings.ociPricing");
  const [service, setService] = useState(item?.service ?? meta?.services[0] ?? "");
  const [sku, setSku] = useState(item?.sku ?? "");
  const [description, setDescription] = useState(item?.description ?? "");
  const [unit, setUnit] = useState(item?.unit ?? meta?.units[0] ?? "");
  const [price, setPrice] = useState(item?.price ?? "");
  const [effectiveFrom, setEffectiveFrom] = useState(toDatetimeLocal(new Date()));
  const [enabled, setEnabled] = useState(true);
  const [reason, setReason] = useState("");
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");

  const normalizedPrice = useMemo(() => normalizeDecimalInput(price), [price]);

  async function submit(event: React.FormEvent) {
    event.preventDefault();
    const startsAt = datetimeLocalToIso(effectiveFrom);
    const normalizedReason = reason.trim();
    if (!normalizedPrice) {
      setError(t("validPrice"));
      return;
    }
    if (!startsAt) {
      setError(t("validStart"));
      return;
    }
    if (mode === "edit" && normalizedReason.length < 3) {
      setError(t("reasonTooShort"));
      return;
    }
    if (mode === "create" && normalizedReason && normalizedReason.length < 3) {
      setError(t("optionalReason"));
      return;
    }
    setSaving(true);
    setError("");
    try {
      if (mode === "create") {
        await api<PricingItem>("/pricing/oci", {
          method: "POST",
          body: JSON.stringify({
            service,
            sku,
            description,
            unit,
            price: normalizedPrice,
            effective_from: startsAt,
            enabled,
            reason: normalizedReason || undefined,
          }),
        });
        await onSaved(t("priceCreated", {sku}));
      } else if (item) {
        await api<PricingItem>(`/pricing/oci/${item.id}`, {
          method: "PATCH",
          body: JSON.stringify({
            price: normalizedPrice,
            description,
            effective_from: startsAt,
            reason: normalizedReason,
          }),
        });
        await onSaved(t("newVersionCreated", {sku: item.sku}));
      }
    } catch (err) {
      setError(apiMessage(err, t("saveFailed")));
    } finally {
      setSaving(false);
    }
  }

  return (
    <div className={styles.overlay} role="presentation">
      <section className={styles.modal} role="dialog" aria-modal="true" aria-labelledby="pricing-form-title">
        <div className={styles.modalHeader}>
          <div>
            <div className="eyebrow">{t("formEyebrow")}</div>
            <h2 id="pricing-form-title">{mode === "create" ? t("newPrice") : t("editPrice")}</h2>
          </div>
          <button className="button small ghost" onClick={onClose} disabled={saving}>{t("close")}</button>
        </div>
        {error && <div className="alert error" role="alert">{error}</div>}
        <form onSubmit={submit} className={styles.form}>
          <div className={styles.formGrid}>
            <ReadOnlyField label={t("provider")} value="OCI" />
            <ReadOnlyField label={t("currency")} value="BRL" />
            <label>
              <span>{t("service")}</span>
              <input
                list="pricing-services"
                value={service}
                onChange={(event) => setService(event.target.value)}
                disabled={mode === "edit" || saving}
                required
              />
            </label>
            <label>
              <span>{t("sku")}</span>
              <input
                value={sku}
                onChange={(event) => setSku(event.target.value)}
                disabled={mode === "edit" || saving}
                required
              />
            </label>
            <label>
              <span>{t("unit")}</span>
              <input
                list="pricing-units"
                value={unit}
                onChange={(event) => setUnit(event.target.value)}
                disabled={mode === "edit" || saving}
                required
              />
            </label>
            <label>
              <span>{t("unitPrice")}</span>
              <input
                inputMode="decimal"
                value={price}
                onChange={(event) => setPrice(event.target.value)}
                placeholder={locale === "en-US" ? "0.00000000" : "0,00000000"}
                disabled={saving}
                required
              />
              <small>{t("decimalHelp")}</small>
            </label>
            <label className={styles.fullField}>
              <span>{t("itemDescription")}</span>
              <input
                value={description}
                onChange={(event) => setDescription(event.target.value)}
                disabled={saving}
                required
              />
            </label>
            <label>
              <span>{t("validFrom")}</span>
              <input
                type="datetime-local"
                value={effectiveFrom}
                onChange={(event) => setEffectiveFrom(event.target.value)}
                disabled={saving}
                required
              />
            </label>
            <label className={styles.fullField}>
              <span>{t("reason")}{mode === "create" ? " (" + t("optional") + ")" : ""}</span>
              <input
                value={reason}
                onChange={(event) => setReason(event.target.value)}
                placeholder={t("reasonPlaceholder")}
                disabled={saving}
                required={mode === "edit"}
                minLength={mode === "edit" ? 3 : undefined}
                maxLength={500}
              />
            </label>
            {mode === "create" && (
              <label className={styles.checkbox}>
                <input
                  type="checkbox"
                  checked={enabled}
                  onChange={(event) => setEnabled(event.target.checked)}
                  disabled={saving}
                />
                {t("createEnabled")}
              </label>
            )}
          </div>
          {mode === "edit" && item && (
            <div className={styles.preview}>
              <strong>{t("nonDestructive")}</strong>
              <span>{t("currentPrice")}: {formatBrlDecimal(item.price, locale)}</span>
              <span>{t("nextPrice")}: {normalizedPrice ? formatBrlDecimal(normalizedPrice, locale) : "—"}</span>
              <span>{t("previewHelp")}</span>
            </div>
          )}
          <div className={styles.formActions}>
            <button type="button" className="button ghost" onClick={onClose} disabled={saving}>{t("cancel")}</button>
            <button type="submit" className="button primary" disabled={saving}>
              {saving ? t("saving") : mode === "create" ? t("createPrice") : t("createVersion")}
            </button>
          </div>
          <datalist id="pricing-services">{meta?.services.map((value) => <option key={value} value={value} />)}</datalist>
          <datalist id="pricing-units">{meta?.units.map((value) => <option key={value} value={value} />)}</datalist>
        </form>
      </section>
    </div>
  );
}

function PricingHistory({ item, onClose }: { item: PricingItem; onClose: () => void }) {
  const locale = useLocale();
  const t = useTranslations("settings.ociPricing");
  const statusWords: Record<string, string> = {active:t("statusActive"),inactive:t("statusInactive"),future:t("statusFuture"),expired:t("statusExpired")};
  const sourceWords: Record<string, string> = {IMPORTED_OCI_CALCULATOR:t("sourceImported"),MANUAL:t("sourceManual")};
  const unitWords: Record<string, string> = {OCPU_HOUR:t("unitOcpu"),GB_RAM_HOUR:t("unitRam"),GB_MONTH:t("unitGb"),VPU_GB_MONTH:t("unitVpu"),INSTANCE_HOUR:t("unitInstance")};
  const [rows, setRows] = useState<PricingItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    let active = true;
    api<PricingItem[]>(`/pricing/oci/${item.id}/history`)
      .then((data) => {
        if (active) setRows(data);
      })
      .catch((err) => {
        if (active) setError(apiMessage(err, t("historyFailed")));
      })
      .finally(() => {
        if (active) setLoading(false);
      });
    return () => { active = false; };
  }, [item.id]);

  return (
    <div className={styles.overlay} role="presentation">
      <section className={`${styles.modal} ${styles.historyModal}`} role="dialog" aria-modal="true" aria-labelledby="pricing-history-title">
        <div className={styles.modalHeader}>
          <div>
            <div className="eyebrow">{t("historyEyebrow")}</div>
            <h2 id="pricing-history-title">{item.sku}</h2>
          </div>
          <button className="button small ghost" onClick={onClose}>{t("close")}</button>
        </div>
        {error && <div className="alert error" role="alert">{error}</div>}
        {loading ? <div className={styles.state}>{t("historyLoading")}</div> : (
          <div className={styles.historyList}>
            {rows.map((row) => (
              <article key={row.id}>
                <div>
                  <strong>{formatBrlDecimal(row.price, locale)}</strong>
                  <span>{row.currency} · {unitWords[row.unit] ?? unitLabel(row.unit)}</span>
                </div>
                <div>
                  <strong>{formatRange(row, locale)}</strong>
                  <span>{statusWords[pricingLifecycleStatus(row)] ?? pricingStatusLabel(pricingLifecycleStatus(row))}</span>
                </div>
                <div>
                  <strong>{sourceWords[row.source] ?? sourceLabel(row.source)}</strong>
                  <span>{row.enabled ? t("statusEnabled") : t("statusDisabled")}</span>
                </div>
              </article>
            ))}
          </div>
        )}
      </section>
    </div>
  );
}

function PricingAuditHistory({ item, onClose }: { item: PricingItem; onClose: () => void }) {
  const locale = useLocale();
  const t = useTranslations("settings.ociPricing");
  const actionWords: Record<string, string> = {CREATED:t("actionCreated"),PRICE_CHANGED:t("actionChanged"),FUTURE_VERSION_CREATED:t("actionFuture"),METADATA_CHANGED:t("actionMetadata"),DEACTIVATED:t("actionDeactivated"),REACTIVATED:t("actionReactivated"),VALIDITY_CHANGED:t("actionValidity"),IMPORTED:t("actionImported")};
  const auditWords = {price:t("price"),status:t("status"),enabled:t("statusEnabled"),disabled:t("statusDisabled"),endValidity:t("endValidity"),descriptionChanged:t("descriptionChanged"),changeRecorded:t("changeRecorded"),open:t("openEnded")};
  const [data, setData] = useState<PricingAuditPage | null>(null);
  const [page, setPage] = useState(1);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    let active = true;
    setLoading(true);
    setError("");
    api<PricingAuditPage>(`/pricing/oci/${item.id}/audit?page=${page}&page_size=${AUDIT_PAGE_SIZE}`)
      .then((result) => {
        if (active) setData(result);
      })
      .catch((err) => {
        if (active) setError(apiMessage(err, t("auditFailed")));
      })
      .finally(() => {
        if (active) setLoading(false);
      });
    return () => { active = false; };
  }, [item.id, page]);

  return (
    <div className={styles.overlay} role="presentation">
      <section className={`${styles.modal} ${styles.historyModal}`} role="dialog" aria-modal="true" aria-labelledby="pricing-audit-title">
        <div className={styles.modalHeader}>
          <div>
            <div className="eyebrow">{t("auditEyebrow")}</div>
            <h2 id="pricing-audit-title">{item.sku}</h2>
          </div>
          <button className="button small ghost" onClick={onClose}>{t("close")}</button>
        </div>
        {error && <div className="alert error" role="alert">{error}</div>}
        {loading ? (
          <div className={styles.state} role="status">{t("auditLoading")}</div>
        ) : !data || data.items.length === 0 ? (
          <div className={styles.state}>{t("auditEmpty")}</div>
        ) : (
          <>
            <div className={styles.historyList}>
              {data.items.map((event) => (
                <article key={event.id}>
                  <div>
                    <strong>{auditActionLabel(event.action, actionWords)}</strong>
                    <span>{formatAuditDate(event.occurred_at, locale)}</span>
                  </div>
                  <div>
                    <strong>{auditActorLabel(event, t("actorSystem"), t("actorRemoved"))}</strong>
                    <span>{event.reason ? t("auditReason") + ": " + event.reason : t("noReason")}</span>
                  </div>
                  <div>
                    <strong>{auditDiff(event, locale, auditWords)}</strong>
                    <span>{t("version")}: {event.pricing_item_id}</span>
                  </div>
                </article>
              ))}
            </div>
            <div className={styles.pagination}>
              <span>{t("eventCount", {count: data.total, page: data.page, pages: Math.max(1, data.total_pages)})}</span>
              <div>
                <button className="button small ghost" disabled={page <= 1 || loading} onClick={() => setPage(page - 1)}>{t("previous")}</button>
                <button className="button small ghost" disabled={page >= data.total_pages || loading} onClick={() => setPage(page + 1)}>{t("next")}</button>
              </div>
            </div>
          </>
        )}
      </section>
    </div>
  );
}

function auditActionLabel(action: string, labels: Record<string, string>) {
  return labels[action] ?? action;
}

function auditActorLabel(event: PricingAuditEvent, system: string, removed: string) {
  if (event.actor_type === "SYSTEM") return system;
  return event.actor_name || event.actor_email || removed;
}

type AuditWords = {price: string; status: string; enabled: string; disabled: string; endValidity: string; descriptionChanged: string; changeRecorded: string; open: string};
function auditDiff(event: PricingAuditEvent, locale: string, words: AuditWords) {
  const before = event.before_data;
  const after = event.after_data;
  if (!before && after?.price) return `${words.price}: ${formatBrlDecimal(after.price, locale)} ${after.currency ?? ""}`.trim();
  if (before?.price !== after?.price && before?.price && after?.price) return `${words.price}: ${formatBrlDecimal(before.price, locale)} → ${formatBrlDecimal(after.price, locale)} ${after.currency ?? before.currency ?? ""}`.trim();
  if (before?.enabled !== after?.enabled && before?.enabled !== undefined && after?.enabled !== undefined) return `${words.status}: ${before.enabled ? words.enabled : words.disabled} → ${after.enabled ? words.enabled : words.disabled}`;
  if (before?.effective_until !== after?.effective_until) return `${words.endValidity}: ${formatAuditOptionalDate(before?.effective_until, locale, words.open)} → ${formatAuditOptionalDate(after?.effective_until, locale, words.open)}`;
  if (before?.description !== after?.description) return words.descriptionChanged;
  return words.changeRecorded;
}

function formatAuditOptionalDate(value: string | null | undefined, locale: string, open: string) {
  return value ? formatAuditDate(value, locale) : open;
}

function formatAuditDate(value: string, locale = "pt-BR") {
  return formatLocaleDateTime(value, locale);
}

function ReadOnlyField({ label, value }: { label: string; value: string }) {
  return <label><span>{label}</span><input value={value} readOnly disabled /></label>;
}

function formatRange(item: PricingItem, locale = "pt-BR") {
  const start = formatLocaleDateTime(item.effective_from, locale);
  const end = item.effective_until ? formatLocaleDateTime(item.effective_until, locale) : (locale === "en-US" ? "open" : "aberta");
  return `${start} → ${end}`;
}

function serviceLabel(value: string) {
  return value === "block_volume" ? "Block Volume" : value === "compute" ? "Compute" : value.replaceAll("_", " ");
}

function statusClass(status: string) {
  return `status-badge ${
    status === "active"
      ? "status-success"
      : status === "future"
        ? "status-running"
        : status === "expired"
          ? "status-untested"
          : "status-error"
  }`;
}

