"use client";

import { FormEvent, useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import { useTranslations } from "next-intl";
import { PageHeader, Section } from "@/components/aven";
import { Alert, Button, Input } from "@/components/ui";
import { MfaSettings, MfaStatus } from "@/components/mfa-settings";
import { api } from "@/lib/api";
import styles from "../settings-page.module.css";

export default function SecurityPage() {
  const t = useTranslations("settings.security");
  const router = useRouter();
  const [mfa, setMfa] = useState<MfaStatus | null>(null);
  const [passwordCode, setPasswordCode] = useState("");
  const [proofCode, setProofCode] = useState("");
  const [password, setPassword] = useState("");
  const [next, setNext] = useState("");
  const [confirm, setConfirm] = useState("");
  const [proof, setProof] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [message, setMessage] = useState("");

  async function load() {
    setMfa(await api<MfaStatus>("/auth/mfa/status"));
  }

  useEffect(() => {
    load().catch((err) => setError(err instanceof Error ? err.message : "ERR_SECURITY_LOAD"));
  }, []);

  async function action(run: () => Promise<void>) {
    setBusy(true);
    setError("");
    setMessage("");
    try {
      await run();
    } catch (err) {
      setError(err instanceof Error ? err.message : "ERR_SECURITY_ACTION");
    } finally {
      setBusy(false);
    }
  }

  function changePassword(event: FormEvent) {
    event.preventDefault();
    if (next !== confirm) {
      setError("ERR_PASSWORD_MISMATCH");
      return;
    }
    void action(async () => {
      await api("/auth/change-password", {
        method: "POST",
        body: JSON.stringify({
          current_password: password,
          new_password: next,
          code: passwordCode,
        }),
      });
      setPasswordCode("");
      setPassword("");
      setNext("");
      setConfirm("");
      router.replace("/login");
    });
  }

  return (
    <>
      <PageHeader
        title={t("title")}
        description={t("description")}
      />

      {error && <Alert variant="danger" title={t("actionFailed")} description={error === "ERR_SECURITY_LOAD" ? t("loadFailed") : error === "ERR_SECURITY_ACTION" ? t("actionFailed") : error === "ERR_PASSWORD_MISMATCH" ? t("passwordMismatch") : error} />}
      {message && <Alert variant="success" title={t("actionDone")} description={message === "IDENTITY_CONFIRMED" ? t("identityConfirmed") : message} />}

      <MfaSettings onStatusChange={setMfa} />

      <div className={styles.sectionGrid}>
        <Section
          appearance="card"
          title={t("changePassword")}
          description={t("changePasswordDescription")}
        >
          <form onSubmit={changePassword} className={styles.formStack}>
            <Input
              label={t("currentPassword")}
              type="password"
              autoComplete="current-password"
              value={password}
              onChange={(event) => setPassword(event.target.value)}
              required
            />
            <Input
              label={t("newPassword")}
              type="password"
              autoComplete="new-password"
              minLength={12}
              maxLength={128}
              value={next}
              onChange={(event) => setNext(event.target.value)}
              required
            />
            <Input
              label={t("confirmPassword")}
              type="password"
              autoComplete="new-password"
              minLength={12}
              maxLength={128}
              value={confirm}
              onChange={(event) => setConfirm(event.target.value)}
              required
            />
            <Input
              label={t("mfaCode", {suffix: !mfa?.enabled ? t("ifEnabled") : ""})}
              autoComplete="one-time-code"
              maxLength={64}
              value={passwordCode}
              onChange={(event) => setPasswordCode(event.target.value)}
              required={mfa?.enabled}
            />
            <div className={styles.formActions}>
              <Button type="submit" loading={busy}>{t("savePassword")}</Button>
            </div>
          </form>
        </Section>

        <Section
          appearance="card"
          title={t("confirmIdentity")}
          description={t("confirmIdentityDescription")}
        >
          <form
            className={styles.formStack}
            onSubmit={(event) => {
              event.preventDefault();
              void action(async () => {
                await api("/auth/reauthenticate", {
                  method: "POST",
                  body: JSON.stringify({ password: proof, code: proofCode }),
                });
                setProofCode("");
                setProof("");
                setMessage("IDENTITY_CONFIRMED");
              });
            }}
          >
            <Input
              label={t("yourPassword")}
              type="password"
              autoComplete="current-password"
              value={proof}
              onChange={(event) => setProof(event.target.value)}
              required
            />
            <Input
              label={t("mfaCode", {suffix: !mfa?.enabled ? t("ifEnabled") : ""})}
              autoComplete="one-time-code"
              maxLength={64}
              value={proofCode}
              onChange={(event) => setProofCode(event.target.value)}
              required={mfa?.enabled}
            />
            <div className={styles.formActions}>
              <Button type="submit" variant="outline" loading={busy}>{t("confirmIdentity")}</Button>
            </div>
          </form>
        </Section>
      </div>
    </>
  );
}

frontend/app/settings/sessions/page.tsx.source:
"use client";

import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import { useLocale, useTranslations } from "next-intl";
import { PageHeader, Section } from "@/components/aven";
import {
  Alert,
  Button,
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
  TableState,
} from "@/components/ui";
import { api, formatDate } from "@/lib/api";
import styles from "../settings-page.module.css";

type Session = {
  id: string;
  created_at: string;
  last_seen_at: string;
  expires_at: string;
  user_agent: string;
  current: boolean;
};

export default function SessionsPage() {
  const locale = useLocale();
  const t = useTranslations("settings.sessions");
  const router = useRouter();
  const [sessions, setSessions] = useState<Session[]>([]);
  const [loaded, setLoaded] = useState(false);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");

  async function load() {
    setSessions(await api<Session[]>("/auth/sessions"));
    setLoaded(true);
  }

  useEffect(() => {
    load().catch((err) => setError(err instanceof Error ? err.message : "ERR_SESSIONS_LOAD"));
  }, []);

  async function action(run: () => Promise<void>) {
    setBusy(true);
    setError("");
    try {
      await run();
    } catch (err) {
      setError(err instanceof Error ? err.message : "ERR_SESSIONS_ACTION");
    } finally {
      setBusy(false);
    }
  }

  return (
    <>
      <PageHeader
        title={t("title")}
        description={t("description")}
        actions={
          <div className={styles.formActions}>
            <Button variant="outline" loading={busy} onClick={() => void action(load)}>
              {t("refresh")}
            </Button>
            <Button
              variant="danger"
              disabled={!loaded}
              loading={busy}
              onClick={() => void action(async () => {
                await api("/auth/logout-all", { method: "POST" });
                router.replace("/login");
              })}
            >
              {t("logoutAll")}
            </Button>
          </div>
        }
      />

      {error && <Alert variant="danger" title={t("errorTitle")} description={error === "ERR_SESSIONS_LOAD" ? t("loadFailed") : error === "ERR_SESSIONS_ACTION" ? t("actionFailed") : error} />}

      <Section
        title={t("activeTitle")}
        description={t("activeDescription")}
      >
        <Table aria-label={t("tableLabel")}>
          <TableHeader>
            <TableRow staticRow>
              <TableHead>{t("column.session")}</TableHead>
              <TableHead>{t("column.browser")}</TableHead>
              <TableHead>{t("column.start")}</TableHead>
              <TableHead>{t("column.lastActivity")}</TableHead>
              <TableHead>{t("column.expires")}</TableHead>
              <TableHead>{t("column.action")}</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {!loaded ? (
              <TableRow staticRow>
                <TableState state="loading" colSpan={6}>{t("loading")}</TableState>
              </TableRow>
            ) : sessions.length === 0 ? (
              <TableRow staticRow>
                <TableState state="empty" colSpan={6}>{t("empty")}</TableState>
              </TableRow>
            ) : sessions.map((session) => (
              <TableRow key={session.id}>
                <TableCell>{session.current ? t("current") : t("other")}</TableCell>
                <TableCell>{session.user_agent || t("unknownBrowser")}</TableCell>
                <TableCell>{formatDate(session.created_at, locale)}</TableCell>
                <TableCell>{formatDate(session.last_seen_at, locale)}</TableCell>
                <TableCell>{formatDate(session.expires_at, locale)}</TableCell>
                <TableCell>
                  <Button
                    size="sm"
                    variant={session.current ? "danger" : "outline"}
                    loading={busy}
                    onClick={() => void action(async () => {
                      await api(`/auth/sessions/${session.id}`, { method: "DELETE" });
                      if (session.current) router.replace("/login");
                      else await load();
                    })}
                  >
                    {session.current ? t("logoutCurrent") : t("revoke")}
                  </Button>
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </Section>
    </>
  );
}

frontend/app/settings/usage-costs/page.t.source:
"use client";

import Link from "next/link";
import {useLocale, useTranslations} from "next-intl";
import { useEffect, useMemo, useRef, useState } from "react";
import { RefreshCw } from "lucide-react";
import { PageHeader } from "@/components/page-header";
import { api } from "@/lib/api";
import type { CloudAccount } from "@/lib/types";
import {
  USAGE_COST_PERIOD_PRESETS,
  buildUsageCostQuery,
  costItemsByCurrency,
  costShare,
  distinctUsageGroups,
  formatUsageCostDate,
  formatUsageCostMoney,
  formatUsageNumber,
  formatUsagePeriodLabel,
  friendlyUsageLabel,
  pricingVersionCount,
  resolveUsageCostPeriod,
  summarizeUsage,
  usageByGroup,
  usageCostGranularity,
} from "@/lib/deepops-usage-costs.mjs";
import styles from "./usage-costs.module.css";

const SHARED_ANALYZER = "__shared__";

type CostComponent = {
  pricing_rule_id: string;
  usage_quantity: string;
  unit_price: string;
  unit_quantity: string;
  pricing_unit: string;
  currency: string;
  effective_from: string;
  effective_until: string | null;
  source: string;
  source_reference: string;
  pricing_verified_at: string;
};

type CostItem = {
  group: string | null;
  period: string | null;
  currency: string;
  gross_estimated_cost: string;
  usage_quantity: string;
  priced_events: number;
  inexact_request_events: number;
  failed_events: number;
  components: CostComponent[];
};

type CostTotal = {
  currency: string;
  gross_estimated_cost: string;
  usage_quantity: string;
};

type UnpricedUsage = {
  operation: string;
  region: string;
  events: number;
  requests: number;
  reason: string;
};

type CostResponse = {
  group_by: string | null;
  granularity: string | null;
  items: CostItem[];
  totals: CostTotal[];
  priced_events: number;
  unpriced_events: number;
  unpriced_usage: UnpricedUsage[];
  is_complete: boolean;
  request_count_is_exact: boolean;
  inexact_request_events: number;
  failed_events: number;
  free_tier_applied: boolean;
  pricing_sources: string[];
  pricing_verified_at: string | null;
  estimation_basis: string;
};

type UsageSummaryItem = {
  group: string | null;
  events: number;
  requests: number;
  metric_queries: number;
  metrics_requested: number;
  failed_events: number;
};

type UsageSummary = {
  group_by: string;
  items: UsageSummaryItem[];
};

type CollectionItem = {
  id: string;
  provider: string;
  account_id: string;
  account_name: string | null;
  started_at: string;
  finished_at: string | null;
  status: string;
};

type CollectionPage = {
  items: CollectionItem[];
  page: number;
  page_size: number;
  total: number;
  total_pages: number;
};

type CostDashboard = {
  summary: CostResponse;
  timeseries: CostResponse;
  account: CostResponse;
  operation: CostResponse;
  collector: CostResponse;
  analyzer: CostResponse;
  collectionRun: CostResponse;
};

type UsageDashboard = {
  operation: UsageSummary;
  account: UsageSummary;
  collector: UsageSummary;
  analyzer: UsageSummary;
  collectionRun: UsageSummary;
};

type FilterOptions = {
  regions: string[];
  operations: string[];
  collectors: string[];
  analyzers: Array<{ value: string; label: string }>;
};

function message(error: unknown, fallback: string) {
  return error instanceof Error && error.message ? error.message : fallback;
}

function accountLabel(account: CloudAccount) {
  return account.name
    ? `${account.name} · ${account.native_account_id}`
    : account.native_account_id;
}

function sourceLabel(source: string) {
  return source === "AWS_OFFICIAL_PRICING" ? "AWS CloudWatch Pricing" : source;
}

function CostTotals({ totals }: { totals: CostTotal[] }) {
  const t = useTranslations("settings.usageCosts");
  const locale = useLocale();
  if (!totals.length) return <strong className={styles.unavailableValue}>{t("unavailable")}</strong>;
  return (
    <div className={styles.moneyStack}>
      {totals.map((total) => (
        <strong key={total.currency}>
          {formatUsageCostMoney(total.gross_estimated_cost, total.currency, locale)}
        </strong>
      ))}
    </div>
  );
}

function CostChart({ response }: { response: CostResponse }) {
  const t = useTranslations("settings.usageCosts");
  const locale = useLocale();
  const groups = costItemsByCurrency(response.items);
  if (!groups.length) {
    return <div className={styles.sectionState}>{t("noPricedChart")}</div>;
  }

  const width = 920;
  const height = 270;
  const padX = 52;
  const padY = 32;

  return (
    <div className={styles.chartGroups}>
      {groups.map(([currency, items]) => {
        const points = [...items].sort((left, right) => String(left.period).localeCompare(String(right.period)));
        const values = points.map((point) => Number(point.gross_estimated_cost));
        const maximum = Math.max(0, ...values);
        const innerWidth = width - padX * 2;
        const innerHeight = height - padY * 2;
        const x = (index: number) => padX + (points.length === 1 ? innerWidth / 2 : (index / (points.length - 1)) * innerWidth);
        const y = (value: number) => padY + (maximum === 0 ? innerHeight : ((maximum - value) / maximum) * innerHeight);
        const path = points.map((point, index) => `${index === 0 ? "M" : "L"} ${x(index)} ${y(Number(point.gross_estimated_cost))}`).join(" ");
        const first = points[0];
        const last = points[points.length - 1];
        return (
          <div className={styles.chartGroup} key={currency}>
            <div className={styles.chartMeta}>
              <strong>{currency}</strong>
              <span>{response.granularity === "monthly" ? t("monthlyBuckets") : t("dailyBuckets")}</span>
            </div>
            <div className={styles.chartScroll}>
              <svg className={styles.chart} viewBox={`0 0 ${width} ${height}`} role="img" aria-label={t("chartAria", {currency})}>
                <line x1={padX} x2={width - padX} y1={height - padY} y2={height - padY} className={styles.axisLine} />
                <path d={path} className={styles.costLine} />
                {points.map((point, index) => (
                  <circle key={`${point.period}-${currency}`} cx={x(index)} cy={y(Number(point.gross_estimated_cost))} r="4" className={styles.costPoint}>
                    <title>{`${point.period}: ${formatUsageCostMoney(point.gross_estimated_cost, currency, locale)}`}</title>
                  </circle>
                ))}
                <text x={padX} y={height - 7} className={styles.axisLabel}>{first.period}</text>
                <text x={width - padX} y={height - 7} textAnchor="end" className={styles.axisLabel}>{last.period}</text>
              </svg>
            </div>
          </div>
        );
      })}
    </div>
  );
}

function BreakdownSection({
  title,
  subtitle,
  kind,
  cost,
  usage,
  accounts,
  showProvenance = false,
}: {
  title: string;
  subtitle: string;
  kind: "account" | "operation" | "collector" | "analyzer";
  cost: CostResponse;
  usage: UsageSummary;
  accounts: CloudAccount[];
  showProvenance?: boolean;
}) {
  const locale = useLocale();
  const t = useTranslations("settings.usageCosts");
  const usageMap = usageByGroup(usage.items);
  const accountMap = new Map(accounts.map((account) => [account.native_account_id, account]));
  const groups = costItemsByCurrency(cost.items);

  const label = (value: string | null) => {
    if (kind === "account" && value) {
      const account = accountMap.get(value);
      return account ? accountLabel(account) : value;
    }
    return friendlyUsageLabel(value, kind, locale);
  };

  const usageForCostGroup = (group: string | null) => {
    if (kind === "analyzer" && group === "Shared / Unattributed") return usageMap.get(null);
    return usageMap.get(group);
  };

  return (
    <section className={styles.panel}>
      <div className={styles.panelHeader}>
        <div>
          <h2>{title}</h2>
          <p>{subtitle}</p>
        </div>
      </div>
      {!groups.length ? (
        <div className={styles.sectionState}>{t("noPricedSlice")}</div>
      ) : (
        <div className={styles.panelBody}>
          {groups.map(([currency, rows]) => (
            <div className={styles.currencyGroup} key={currency}>
              <div className={styles.currencyHeading}><strong>{currency}</strong><span>{t("sortedByCost")}</span></div>
              <div className={styles.tableWrap}>
                <table className={styles.table}>
                  <thead>
                    <tr>
                      <th>{kind === "account" ? t("account") : kind === "operation" ? t("operation") : kind === "collector" ? t("collector") : t("analyzer")}</th>
                      <th>{t("requests")}</th>
                      <th>{t("metricQueries")}</th>
                      <th>{t("failures")}</th>
                      <th>{t("estimatedCost")}</th>
                      <th>{t("costShare")}</th>
                    </tr>
                  </thead>
                  <tbody>
                    {rows.map((row) => {
                      const technical = usageForCostGroup(row.group);
                      const share = costShare(row, rows);
                      return (
                        <tr key={`${currency}-${row.group ?? "none"}`}>
                          <td>
                            <strong>{label(row.group)}</strong>
                            {showProvenance && row.components.length > 0 && (
                              <details className={styles.provenance}>
                                <summary>{t("appliedPricing")}</summary>
                                {row.components.map((component, index) => (
                                  <div key={`${component.pricing_rule_id}-${component.effective_from}-${index}`}>
                                    <span>{t("rule", {id: component.pricing_rule_id})}</span>
                                    <span>{formatUsageNumber(component.usage_quantity, locale)} {component.pricing_unit}</span>
                                    <span>{formatUsageCostMoney(component.unit_price, component.currency, locale)} / {formatUsageNumber(component.unit_quantity, locale)} {component.pricing_unit}</span>
                                    <span>{t("effectiveFrom", {date: formatUsageCostDate(component.effective_from, locale)})}</span>
                                    <span>{t("source", {source: sourceLabel(component.source)})}</span>
                                  </div>
                                ))}
                              </details>
                            )}
                          </td>
                          <td>{formatUsageNumber(technical?.requests ?? 0, locale)}</td>
                          <td>{formatUsageNumber(technical?.metric_queries ?? 0, locale)}</td>
                          <td>{formatUsageNumber(technical?.failed_events ?? row.failed_events, locale)}</td>
                          <td><strong>{formatUsageCostMoney(row.gross_estimated_cost, currency, locale)}</strong></td>
                          <td>{share === null ? "—" : `${share.toLocaleString(locale, { maximumFractionDigits: 1 })}%`}</td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            </div>
          ))}
        </div>
      )}
    </section>
  );
}

export default function AvenUsageCostsPage() {
  const t = useTranslations("settings.usageCosts");
  const locale = useLocale();
  const [preset, setPreset] = useState("this-month");
  const [customStart, setCustomStart] = useState("");
  const [customEnd, setCustomEnd] = useState("");
  const [accountId, setAccountId] = useState("");
  const [region, setRegion] = useState("");
  const [operation, setOperation] = useState("");
  const [collector, setCollector] = useState("");
  const [analyzer, setAnalyzer] = useState("");
  const [refreshToken, setRefreshToken] = useState(0);

  const [accounts, setAccounts] = useState<CloudAccount[]>([]);
  const [options, setOptions] = useState<FilterOptions>({ regions: [], operations: [], collectors: [], analyzers: [] });
  const [optionsError, setOptionsError] = useState("");

  const [cost, setCost] = useState<CostDashboard | null>(null);
  const [usage, setUsage] = useState<UsageDashboard | null>(null);
  const [collections, setCollections] = useState<CollectionItem[]>([]);
  const [costLoading, setCostLoading] = useState(true);
  const [usageLoading, setUsageLoading] = useState(true);
  const [runsLoading, setRunsLoading] = useState(true);
  const [costError, setCostError] = useState("");
  const [usageError, setUsageError] = useState("");
  const [runsError, setRunsError] = useState("");
  const sequence = useRef(0);

  const period = useMemo(() => resolveUsageCostPeriod(preset, customStart, customEnd), [preset, customStart, customEnd]);
  const granularity = usageCostGranularity(period);
  const awsAccounts = useMemo(() => accounts.filter((account) => account.provider === "aws"), [accounts]);
  const selectedAccount = useMemo(() => awsAccounts.find((account) => String(account.id) === accountId) ?? null, [accountId, awsAccounts]);

  const canonicalFilters = useMemo(() => {
    if (!period) return null;
    return {
      date_from: period.date_from,
      date_to: period.date_to,
      cloud_account_id: accountId || undefined,
      region: region || undefined,
      operation: operation || undefined,
      collector: collector || undefined,
      analyzer: analyzer || undefined,
    };
  }, [period, accountId, region, operation, collector, analyzer]);

  useEffect(() => {
    const controller = new AbortController();
    api<CloudAccount[]>("/cloud-accounts", { signal: controller.signal })
      .then(setAccounts)
      .catch((error) => {
        if (!controller.signal.aborted) setOptionsError(message(error, t("accountsLoadFailed")));
      });
    return () => controller.abort();
  }, []);

  useEffect(() => {
    if (!period) return;
    const controller = new AbortController();
    const periodQuery = { date_from: period.date_from, date_to: period.date_to };
    const summary = (groupBy: string) => api<UsageSummary>(`/usage/cloudwatch/summary${buildUsageCostQuery(periodQuery, { group_by: groupBy })}`, { signal: controller.signal });
    setOptionsError("");
    Promise.all([summary("region"), summary("operation"), summary("collector"), summary("analyzer")])
      .then(([regions, operations, collectors, analyzers]) => {
        if (controller.signal.aborted) return;
        const analyzerOptions = distinctUsageGroups(analyzers.items).map((value) => ({ value, label: friendlyUsageLabel(value, "analyzer", locale) }));
        if (analyzers.items.some((item) => item.group === null)) {
          analyzerOptions.unshift({ value: SHARED_ANALYZER, label: t("shared") });
        }
        setOptions({
          regions: distinctUsageGroups(regions.items),
          operations: distinctUsageGroups(operations.items),
          collectors: distinctUsageGroups(collectors.items),
          analyzers: analyzerOptions,
        });
      })
      .catch((error) => {
        if (!controller.signal.aborted) setOptionsError(message(error, t("telemetryOptionsFailed")));
      });
    return () => controller.abort();
  }, [period, refreshToken]);

  useEffect(() => {
    if (!canonicalFilters || !period) {
      setCost(null);
      setUsage(null);
      return;
    }
    const controller = new AbortController();
    const current = ++sequence.current;
    const signal = controller.signal;
    const costQuery = (suffix: string, extra: Record<string, string> = {}) => api<CostResponse>(`/deepops-costs/cloudwatch/${suffix}${buildUsageCostQuery(canonicalFilters, extra)}`, { signal });
    const usageQuery = (groupBy: string) => api<UsageSummary>(`/usage/cloudwatch/summary${buildUsageCostQuery(canonicalFilters, { group_by: groupBy })}`, { signal });

    setCostLoading(true);
    setUsageLoading(true);
    setRunsLoading(true);
    setCostError("");
    setUsageError("");
    setRunsError("");

    Promise.all([
      costQuery("summary"),
      costQuery("timeseries", { granularity }),
      costQuery("breakdown", { group_by: "account" }),
      costQuery("breakdown", { group_by: "operation" }),
      costQuery("breakdown", { group_by: "collector" }),
      costQuery("breakdown", { group_by: "analyzer" }),
      costQuery("breakdown", { group_by: "collection_run" }),
    ])
      .then(([summary, timeseries, account, operationCost, collectorCost, analyzerCost, collectionRun]) => {
        if (current === sequence.current && !signal.aborted) setCost({ summary, timeseries, account, operation: operationCost, collector: collectorCost, analyzer: analyzerCost, collectionRun });
      })
      .catch((error) => {
        if (!signal.aborted && current === sequence.current) setCostError(message(error, t("costsLoadFailed")));
      })
      .finally(() => {
        if (!signal.aborted && current === sequence.current) setCostLoading(false);
      });

    Promise.all([
      usageQuery("operation"),
      usageQuery("account"),
      usageQuery("collector"),
      usageQuery("analyzer"),
      usageQuery("collection_run"),
    ])
      .then(([operationUsage, account, collectorUsage, analyzerUsage, collectionRun]) => {
        if (current === sequence.current && !signal.aborted) setUsage({ operation: operationUsage, account, collector: collectorUsage, analyzer: analyzerUsage, collectionRun });
      })
      .catch((error) => {
        if (!signal.aborted && current === sequence.current) setUsageError(message(error, t("telemetryLoadFailed")));
      })
      .finally(() => {
        if (!signal.aborted && current === sequence.current) setUsageLoading(false);
      });

    const runParams = new URLSearchParams({
      provider: "aws",
      date_from: period.date_from,
      date_to: period.date_to,
      page: "1",
      page_size: "100",
      sort: "started_at",
      order: "desc",
    });
    if (selectedAccount) runParams.set("account_id", selectedAccount.native_account_id);
    api<CollectionPage>(`/collections?${runParams}`, { signal })
      .then((response) => {
        if (current === sequence.current && !signal.aborted) setCollections(response.items);
      })
      .catch((error) => {
        if (!signal.aborted && current === sequence.current) setRunsError(message(error, t("collectionsLoadFailed")));
      })
      .finally(() => {
        if (!signal.aborted && current === sequence.current) setRunsLoading(false);
      });

    return () => controller.abort();
  }, [canonicalFilters, period, granularity, selectedAccount, refreshToken]);

  const usageTotal = useMemo(() => summarizeUsage(usage?.operation.items ?? []), [usage]);
  const accountMap = useMemo(() => new Map(awsAccounts.map((account) => [account.native_account_id, account])), [awsAccounts]);
  const runMetadata = useMemo(() => new Map(collections.map((run) => [run.id, run])), [collections]);
  const runUsage = useMemo(() => usageByGroup(usage?.collectionRun.items ?? []), [usage]);
  const runCost = useMemo(() => {
    const grouped = new Map<string, CostItem[]>();
    for (const item of cost?.collectionRun.items ?? []) {
      if (!item.group) continue;
      const rows = grouped.get(item.group) ?? [];
      rows.push(item);
      grouped.set(item.group, rows);
    }
    return grouped;
  }, [cost]);
  const runIds = useMemo(() => {
    const ids = new Set<string>();
    for (const item of usage?.collectionRun.items ?? []) if (item.group) ids.add(item.group);
    for (const item of cost?.collectionRun.items ?? []) if (item.group) ids.add(item.group);
    return [...ids].sort((left, right) => {
      const leftTime = runMetadata.get(left)?.started_at ?? "";
      const rightTime = runMetadata.get(right)?.started_at ?? "";
      return rightTime.localeCompare(leftTime);
    }).slice(0, 20);
  }, [usage, cost, runMetadata]);
  const unassignedRunUsage = runUsage.get(null);
  const versions = pricingVersionCount(cost?.summary.items ?? []);
  const hasUsage = usageTotal.events > 0;

  return (
    <>
      <PageHeader
        eyebrow={t("eyebrow")}
        title={t("title")}
        description={t("description")}
        actions={<button className="button secondary" onClick={() => setRefreshToken((value) => value + 1)}><RefreshCw size={16} /> {t("refresh")}</button>}
      />

      <section className={styles.filtersPanel} aria-label={t("filtersAria")}>
        <div className={styles.filtersGrid}>
          <label className={styles.field}>
            <span>{t("period")}</span>
            <select value={preset} onChange={(event) => setPreset(event.target.value)}>
              {USAGE_COST_PERIOD_PRESETS.map((item) => <option value={item.value} key={item.value}>{({today:t("presetToday"),"last-7-days":t("preset7"),"this-month":t("presetMonth"),"previous-month":t("presetPrevious"),"last-3-months":t("preset3"),custom:t("presetCustom")} as Record<string,string>)[item.value] ?? item.label}</option>)}
            </select>
          </label>
          <label className={styles.field}>
            <span>{t("awsAccount")}</span>
            <select value={accountId} onChange={(event) => setAccountId(event.target.value)}>
              <option value="">{t("allAuthorized")}</option>
              {awsAccounts.map((account) => <option value={account.id} key={account.id}>{accountLabel(account)}</option>)}
            </select>
          </label>
          <label className={styles.field}>
            <span>{t("operation")}</span>
            <select value={operation} onChange={(event) => setOperation(event.target.value)}>
              <option value="">{t("allFeminine")}</option>
              {options.operations.map((value) => <option value={value} key={value}>{value}</option>)}
            </select>
          </label>
          <label className={styles.field}>
            <span>{t("region")}</span>
            <select value={region} onChange={(event) => setRegion(event.target.value)}>
              <option value="">{t("allFeminine")}</option>
              {options.regions.map((value) => <option value={value} key={value}>{value}</option>)}
            </select>
          </label>
          <label className={styles.field}>
            <span>{t("collector")}</span>
            <select value={collector} onChange={(event) => setCollector(event.target.value)}>
              <option value="">{t("allMasculine")}</option>
              {options.collectors.map((value) => <option value={value} key={value}>{friendlyUsageLabel(value, "collector", locale)}</option>)}
            </select>
          </label>
          <label className={styles.field}>
            <span>{t("analyzer")}</span>
            <select value={analyzer} onChange={(event) => setAnalyzer(event.target.value)}>
              <option value="">{t("allMasculine")}</option>
              {options.analyzers.map((item) => <option value={item.value} key={item.value}>{friendlyUsageLabel(item.value === SHARED_ANALYZER ? null : item.value, "analyzer", locale)}</option>)}
            </select>
          </label>
        </div>
        {preset === "custom" && (
          <div className={styles.customDates}>
            <label className={styles.field}><span>{t("from")}</span><input type="date" value={customStart} onChange={(event) => setCustomStart(event.target.value)} /></label>
            <label className={styles.field}><span>{t("to")}</span><input type="date" value={customEnd} onChange={(event) => setCustomEnd(event.target.value)} /></label>
          </div>
        )}
        <div className={styles.filterMeta}>
          <span>{formatUsagePeriodLabel(period, locale)}</span>
          <span>{t("filterTime")} <code>occurred_at</code>.</span>
        </div>
        {!period && <p className={styles.warning} role="alert">{t("invalidCustom")}</p>}
        {optionsError && <p className={styles.warning} role="alert">{optionsError}</p>}
      </section>

      {cost?.summary && !cost.summary.is_complete && (
        <div className={styles.warningBanner} role="alert">
          <strong>{t("incompleteEstimate")}</strong> {t("incompleteEstimateNote")}
        </div>
      )}

      <div className={styles.kpiGrid}>
        <article className={styles.kpiCard}>
          <span>{t("avenCost")}</span>
          {costLoading ? <strong>{t("loading")}</strong> : costError ? <strong>{t("unavailable")}</strong> : <CostTotals totals={cost?.summary.totals ?? []} />}
          <small>{t("rawEstimate")}</small>
        </article>
        <article className={styles.kpiCard}>
          <span>{t("cloudwatchRequests")}</span>
          <strong>{usageLoading ? t("loading") : formatUsageNumber(usageTotal.requests, locale)}</strong>
          <small>{t("requestsObserved")}</small>
        </article>
        <article className={styles.kpiCard}>
          <span>{t("metricQueries")}</span>
          <strong>{usageLoading ? t("loading") : formatUsageNumber(usageTotal.metric_queries, locale)}</strong>
          <small>{t("metricQueriesNote")}</small>
        </article>
        <article className={styles.kpiCard}>
          <span>{t("failures")}</span>
          <strong>{usageLoading ? t("loading") : formatUsageNumber(usageTotal.failed_events, locale)}</strong>
          <small>{t("failuresNote")}</small>
        </article>
      </div>

      {usageError && <div className={styles.errorBanner} role="alert"><strong>{t("telemetryError")}</strong> {usageError}</div>}
      {costError && <div className={styles.errorBanner} role="alert"><strong>{t("costError")}</strong> {costError} {t("telemetryAvailable")}</div>}

      {!usageLoading && !usageError && !hasUsage && (
        <section className={styles.emptyState}>
          <h2>{t("noUsageTitle")}</h2>
          <p>{t("noUsageNote")}</p>
        </section>
      )}

      {hasUsage && cost?.summary && cost.summary.totals.length === 0 && cost.summary.unpriced_events > 0 && (
        <div className={styles.warningBanner} role="alert">{t("unpricedWarning")}</div>
      )}

      <section className={styles.panel}>
        <div className={styles.panelHeader}>
          <div><h2>{t("timelineTitle")}</h2><p>{t("timelineDescription")}</p></div>
          {cost?.summary && !cost.summary.is_complete && <span className={styles.warningBadge}>{t("partialSeries")}</span>}
        </div>
        <div className={styles.panelBody}>
          {costLoading ? <div className={styles.sectionState}>{t("loadingCostTrend")}</div> : costError ? <div className={styles.sectionError}>{t("costTrendError")}</div> : cost ? <CostChart response={cost.timeseries} /> : null}
        </div>
      </section>

      <section className={styles.panel}>
        <div className={styles.panelHeader}><div><h2>{t("technicalUsage")}</h2><p>{t("technicalUsageNote")}</p></div></div>
        <div className={styles.panelBody}>
          {usageLoading ? <div className={styles.sectionState}>{t("loadingTechnical")}</div> : usageError ? <div className={styles.sectionError}>{t("technicalError")}</div> : (
            <div className={styles.usageGrid}>
              <div><span>{t("events")}</span><strong>{formatUsageNumber(usageTotal.events, locale)}</strong></div>
              <div><span>{t("requests")}</span><strong>{formatUsageNumber(usageTotal.requests, locale)}</strong></div>
              <div><span>{t("metricQueries")}</span><strong>{formatUsageNumber(usageTotal.metric_queries, locale)}</strong></div>
              <div><span>{t("requestedMetrics")}</span><strong>{formatUsageNumber(usageTotal.metrics_requested, locale)}</strong></div>
            </div>
          )}
        </div>
      </section>

      {cost && usage && (
        <div className={styles.breakdownGrid}>
          <BreakdownSection title={t("costByAccount")} subtitle={t("costByAccountNote")} kind="account" cost={cost.account} usage={usage.account} accounts={awsAccounts} />
          <BreakdownSection title={t("costByOperation")} subtitle={t("costByOperationNote")} kind="operation" cost={cost.operation} usage={usage.operation} accounts={awsAccounts} showProvenance />
          <BreakdownSection title={t("costByCollector")} subtitle={t("costByCollectorNote")} kind="collector" cost={cost.collector} usage={usage.collector} accounts={awsAccounts} />
          <BreakdownSection title={t("costByAnalyzer")} subtitle={t("costByAnalyzerNote")} kind="analyzer" cost={cost.analyzer} usage={usage.analyzer} accounts={awsAccounts} />
        </div>
      )}

      {cost?.summary.unpriced_usage && cost.summary.unpriced_usage.length > 0 && (
        <section className={styles.panel}>
          <div className={styles.panelHeader}><div><h2>{t("unpricedUsage")}</h2><p>{t("unpricedUsageNote")}</p></div><span className={styles.warningBadge}>{t("eventCount", {count: formatUsageNumber(cost.summary.unpriced_events, locale)})}</span></div>
          <div className={styles.panelBody}>
            <div className={styles.tableWrap}>
              <table className={styles.table}>
                <thead><tr><th>{t("operation")}</th><th>{t("region")}</th><th>{t("events")}</th><th>{t("requests")}</th><th>{t("reason")}</th></tr></thead>
                <tbody>{cost.summary.unpriced_usage.map((item) => <tr key={`${item.operation}-${item.region}`}><td>{item.operation}</td><td>{item.region}</td><td>{formatUsageNumber(item.events, locale)}</td><td>{formatUsageNumber(item.requests, locale)}</td><td>{item.reason}</td></tr>)}</tbody>
              </table>
            </div>
          </div>
        </section>
      )}

      <section className={styles.panel}>
        <div className={styles.panelHeader}><div><h2>{t("recentRuns")}</h2><p>{t("recentRunsNote")}</p></div></div>
        <div className={styles.panelBody}>
          {runsLoading || usageLoading || costLoading ? <div className={styles.sectionState}>{t("runsLoading")}</div> : runsError ? <div className={styles.sectionError}>{runsError}</div> : runIds.length === 0 ? <div className={styles.sectionState}>{t("noRecentRuns")}</div> : (
            <div className={styles.tableWrap}>
              <table className={styles.table}>
                <thead><tr><th>CollectionRun</th><th>{t("start")}</th><th>{t("account")}</th><th>{t("status")}</th><th>{t("requests")}</th><th>{t("metricQueries")}</th><th>{t("estimatedCost")}</th></tr></thead>
                <tbody>
                  {runIds.map((runId) => {
                    const run = runMetadata.get(runId);
                    const technical = runUsage.get(runId);
                    const costs = runCost.get(runId) ?? [];
                    const account = run ? accountMap.get(run.account_id) : undefined;
                    return (
                      <tr key={runId}>
                        <td><Link href={`/collections/${runId}`}>{runId.slice(0, 8)}…</Link></td>
                        <td>{formatUsageCostDate(run?.started_at, locale)}</td>
                        <td>{run ? (account ? accountLabel(account) : run.account_name || run.account_id) : "—"}</td>
                        <td><span className={run?.status === "FAILED" ? styles.failedStatus : styles.status}>{run?.status === "FAILED" ? t("statusFailed") : run?.status === "SUCCESS" ? t("statusSuccess") : run?.status === "RUNNING" ? t("statusRunning") : run?.status === "COMPLETED_WITH_WARNINGS" ? t("statusWarnings") : run?.status ?? "—"}</span></td>
                        <td>{formatUsageNumber(technical?.requests ?? 0, locale)}</td>
                        <td>{formatUsageNumber(technical?.metric_queries ?? 0, locale)}</td>
                        <td>{costs.length ? costs.map((item) => <div key={item.currency}>{formatUsageCostMoney(item.gross_estimated_cost, item.currency, locale)}</div>) : t("noPricedCost")}</td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          )}
          {unassignedRunUsage && <p className={styles.note}>{t("unassignedRequests", {count: formatUsageNumber(unassignedRunUsage.requests, locale)})}</p>}
        </div>
      </section>

      <section className={styles.panel}>
        <div className={styles.panelHeader}><div><h2>{t("aboutEstimate")}</h2><p>{t("aboutEstimateNote")}</p></div></div>
        <div className={styles.assumptions}>
          <div><span>{t("definition")}</span><strong>{t("definitionValue")}</strong><p>{t("definitionNote")}</p></div>
          <div><span>{t("pricingSource")}</span><strong>{cost?.summary.pricing_sources.length ? cost.summary.pricing_sources.map(sourceLabel).join(", ") : t("noAppliedRule")}</strong><p>{t("verifiedAt", {date: formatUsageCostDate(cost?.summary.pricing_verified_at, locale)})}</p></div>
          <div><span>{t("freeTier")}</span><strong>{cost?.summary.free_tier_applied ? t("freeTierApplied") : t("notApplied")}</strong><p>{t("freeTierNote")}</p></div>
          <div><span>{t("completeness")}</span><strong>{cost?.summary.is_complete ? t("complete") : t("incomplete")}</strong><p>{t("completenessEvents", {unpriced: formatUsageNumber(cost?.summary.unpriced_events ?? 0, locale), inexact: formatUsageNumber(cost?.summary.inexact_request_events ?? 0, locale)})}</p></div>
          <div><span>{t("versions")}</span><strong>{versions > 1 ? t("versionsPlural", {count: versions}) : versions === 1 ? t("versionsOne") : t("versionsNone")}</strong><p>{t("versionsNote")}</p></div>
          <div><span>{t("currency")}</span><strong>{t("noFX")}</strong><p>{t("noFXNote")}</p></div>
        </div>
        {cost?.summary.estimation_basis && <p className={styles.estimationBasis}>{cost.summary.estimation_basis}</p>}
      </section>
    </>
  );
}

