"use client";

import Link from "next/link";
import { useTranslations } from "next-intl";
import { FormEvent, useEffect, useRef, useState } from "react";
import { LockKeyhole } from "lucide-react";
import { AuthLayout } from "@/components/auth/auth-layout";
import {
  Alert,
  Button,
  Card,
  CardContent,
  CardFooter,
  CardHeader,
  Input,
} from "@/components/ui";
import { api } from "@/lib/api";
import { authErrorKey, type AuthErrorKey } from "@/lib/auth-error";
import { iconDefaults } from "@/lib/iconography";
import styles from "./access-form.module.css";

export function AccessForm({ mode }: { mode: "forgot" | "reset" | "invite" }) {
  const t = useTranslations("auth");
  const initialized = useRef("");
  const [token, setToken] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [confirm, setConfirm] = useState("");
  const [error, setError] = useState<AuthErrorKey | "passwordMismatch" | "invalidLink" | null>(null);
  const [message, setMessage] = useState(false);
  const [loading, setLoading] = useState(false);
  const [ready, setReady] = useState(mode === "forgot");

  useEffect(() => {
    if (mode === "forgot" || initialized.current === mode) return;
    initialized.current = mode;
    const value = new URLSearchParams(window.location.hash.slice(1)).get("token") || "";
    setToken(value);
    window.history.replaceState(null, "", window.location.pathname);
    if (value.length !== 43) {
      setError("invalidLink");
    }
    setReady(true);
  }, [mode]);

  async function submit(event: FormEvent) {
    event.preventDefault();
    setError(null);
    if (mode !== "forgot" && password !== confirm) {
      setError("passwordMismatch");
      return;
    }
    setLoading(true);
    try {
      const path = mode === "forgot"
        ? "/auth/forgot-password"
        : mode === "invite"
          ? "/auth/accept-invitation"
          : "/auth/reset-password";
      await api<{ message: string }>(path, {
        method: "POST",
        body: JSON.stringify(mode === "forgot" ? { email } : { token, password }),
      });
      setMessage(true);
      setPassword("");
      setConfirm("");
      setToken("");
    } catch (err) {
      setError(authErrorKey(err, "access"));
    } finally {
      setLoading(false);
    }
  }

  const title = t(`access.${mode}.title`);
  const description = mode === "forgot"
    ? t("access.forgot.description")
    : t("access.passwordInstructions", { min: 12, max: 128 });
  const submitLabel = t(`access.${mode}.submit`);
  const submitDisabled = !ready || (mode !== "forgot" && token.length !== 43);

  return (
    <AuthLayout>
      <Card className={styles.card}>
        <CardHeader className={styles.header}>
          <span className={styles.icon} aria-hidden="true">
            <LockKeyhole {...iconDefaults} />
          </span>
          <h1 className={styles.title}>{title}</h1>
          <p className={styles.description}>{description}</p>
        </CardHeader>

        <CardContent className={styles.content}>
          {message ? (
            <Alert variant="success" description={t(`access.${mode}.success`)} />
          ) : (
            <form className={styles.form} onSubmit={submit}>
              {mode === "forgot" ? (
                <Input
                  type="email"
                  label={t("access.email")}
                  autoComplete="email"
                  maxLength={254}
                  value={email}
                  onChange={(event) => setEmail(event.target.value)}
                  required
                />
              ) : (
                <>
                  <Input
                    type="password"
                    label={t("access.newPassword")}
                    autoComplete="new-password"
                    minLength={12}
                    maxLength={128}
                    value={password}
                    onChange={(event) => setPassword(event.target.value)}
                    required
                  />
                  <Input
                    type="password"
                    label={t("access.confirmPassword")}
                    autoComplete="new-password"
                    minLength={12}
                    maxLength={128}
                    value={confirm}
                    onChange={(event) => setConfirm(event.target.value)}
                    required
                  />
                </>
              )}
              <Button
                className={styles.submit}
                type="submit"
                loading={loading}
                disabled={submitDisabled}
              >
                {submitLabel}
              </Button>
            </form>
          )}

          {error && <Alert variant="danger" description={error === "passwordMismatch" ? t("access.passwordMismatch") : error === "invalidLink" ? t("access.invalidLink") : t(`errors.${error}`)} />}
        </CardContent>

        <CardFooter className={styles.footer}>
          <Link className={styles.link} href="/login">
            {t("access.backToLogin")}
          </Link>
        </CardFooter>
      </Card>
    </AuthLayout>
  );
}

frontend/components/app-shell.tsx.source:
"use client";

import { useRouter, usePathname } from "next/navigation";
import { useTranslations } from "next-intl";
import { useEffect, useState, type ReactNode } from "react";
import { ApplicationShell, type ShellUser } from "@/components/app-shell/application-shell";
import { Button, Spinner } from "@/components/ui";
import { api, ApiError } from "@/lib/api";
import { clearApiQueryCache } from "@/lib/server-state";
import styles from "@/components/app-shell/app-shell.module.css";

const publicRoutes = [
  "/mfa-setup",
  "/login",
  "/forgot-password",
  "/reset-password",
  "/accept-invitation",
];

export function AppShell({ children }: { children: ReactNode }) {
  const pathname = usePathname();
  const tSession = useTranslations("shell.session");
  const tCommon = useTranslations("common.actions");
  const router = useRouter();
  const [ready, setReady] = useState(false);
  const [session, setSession] = useState<ShellUser | null>(null);
  const [error, setError] = useState("");
  const [leaving, setLeaving] = useState(false);
  const [retry, setRetry] = useState(0);
  const isPublic = publicRoutes.includes(pathname);

  useEffect(() => {
    const clearPrivateCache = () => clearApiQueryCache();
    window.addEventListener("deepops:session-invalidated", clearPrivateCache);
    return () => window.removeEventListener("deepops:session-invalidated", clearPrivateCache);
  }, []);

  useEffect(() => {
    let active = true;
    window.localStorage.removeItem("nuvemiq_token");
    setReady(false);
    setError("");

    if (isPublic) {
      clearApiQueryCache();
      setSession(null);
      setReady(true);
      return;
    }

    api<ShellUser>("/auth/me", {}, false)
      .then((user) => {
        if (!active) return;
        setSession(user);
        setReady(true);
      })
      .catch((err) => {
        if (!active) return;
        if (err instanceof ApiError && err.status === 401) {
          clearApiQueryCache();
          router.replace("/login");
        } else {
          setError("SESSION_VERIFICATION_FAILED");
        }
      });

    return () => {
      active = false;
    };
  }, [isPublic, router, retry]);

  async function logout() {
    setLeaving(true);
    setError("");
    try {
      await api("/auth/logout", { method: "POST" });
      clearApiQueryCache();
      router.replace("/login");
    } catch (err) {
      setError(err instanceof Error ? err.message : "SIGN_OUT_FAILED");
    } finally {
      setLeaving(false);
    }
  }

  const displayError = error === "SESSION_VERIFICATION_FAILED"
    ? tSession("verificationFailed")
    : error === "SIGN_OUT_FAILED" ? tSession("signOutFailed") : error;

  if (error && !ready) {
    return (
      <main className={styles.bootScreen}>
        <p role="alert">{displayError}</p>
        <Button onClick={() => setRetry((value) => value + 1)}>{tCommon("retry")}</Button>
      </main>
    );
  }

  if (!ready) {
    return (
      <main className={styles.bootScreen} aria-live="polite">
        <Spinner label={tSession("checkingAccess")} />
        <span>{tSession("checkingAccessProgress")}</span>
      </main>
    );
  }

  if (isPublic) return <>{children}</>;

  return (
    <ApplicationShell
      user={session}
      leaving={leaving}
      statusMessage={displayError}
      onLogout={logout}
    >
      {children}
    </ApplicationShell>
  );
}

frontend/components/app-shell/applicatio.source:
"use client";

import Link from "next/link";
import { useTranslations } from "next-intl";
import { usePathname } from "next/navigation";
import {
  Check,
  ChevronDown,
  ChevronLeft,
  ChevronRight,
  LogOut,
  Menu,
  Monitor,
  Moon,
  Sun,
  type LucideIcon,
} from "lucide-react";
import { useEffect, useState, type ReactNode } from "react";
import { BrandLogo } from "@/components/brand/brand-logo";
import { LanguageControl } from "./language-control";
import { useTheme } from "@/components/theme-provider";
import {
  Avatar,
  Divider,
  Drawer,
  DrawerContent,
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
  IconButton,
  Tooltip,
} from "@/components/ui";
import { brand } from "@/lib/brand";
import { iconDefaults, iconSizes } from "@/lib/iconography";
import {
  parseSidebarCollapsed,
  serializeSidebarCollapsed,
  SIDEBAR_STORAGE_KEY,
  type ThemePreference,
} from "@/lib/ui-preferences.mjs";
import { isNavigationItemActive, navigation, type NavigationItem } from "./navigation";
import styles from "./app-shell.module.css";

export interface ShellUser {
  name?: string | null;
  full_name?: string | null;
  email?: string | null;
  role?: string | null;
}

interface ApplicationShellProps {
  children: ReactNode;
  user?: ShellUser | null;
  leaving?: boolean;
  statusMessage?: string;
  onLogout(): void | Promise<void>;
}

const themeOptions: ReadonlyArray<{
  value: ThemePreference;
  icon: LucideIcon;
}> = [
  { value: "light", icon: Sun },
  { value: "dark", icon: Moon },
  { value: "system", icon: Monitor },
];

function AvenBrand({ compact = false }: { compact?: boolean }) {
  const t = useTranslations("shell.navigation");
  return (
    <Link className={styles.brandLink} href="/" aria-label={`${brand.name} — ${t("dashboard")}`}>
      <span className={compact ? styles.brandWordmarkMobile : styles.brandWordmark} aria-hidden="true">
        <BrandLogo variant="wordmark" decorative />
      </span>
      {!compact && (
        <span className={styles.brandMark} aria-hidden="true">
          <BrandLogo variant="verticalNoTagline" decorative />
        </span>
      )}
      <span className={styles.srOnly}>{brand.name}</span>
    </Link>
  );
}

function NavigationLink({
  item,
  label,
  pathname,
  collapsed,
  onNavigate,
}: {
  item: NavigationItem;
  label: string;
  pathname: string;
  collapsed: boolean;
  onNavigate?: () => void;
}) {
  const Icon = item.icon;
  const active = isNavigationItemActive(pathname, item);
  const link = (
    <Link
      className={styles.navItem}
      href={item.href}
      aria-current={active ? "page" : undefined}
      aria-label={collapsed ? label : undefined}
      onClick={onNavigate}
    >
      <Icon {...iconDefaults} size={iconSizes.lg} aria-hidden="true" />
      <span className={styles.navLabel}>{label}</span>
    </Link>
  );

  return collapsed ? <Tooltip className={styles.navTooltip} content={label}>{link}</Tooltip> : link;
}

function SidebarNavigation({
  pathname,
  collapsed,
  onNavigate,
}: {
  pathname: string;
  collapsed: boolean;
  onNavigate?: () => void;
}) {
  const tNavigation = useTranslations("shell.navigation");
  const tSidebar = useTranslations("shell.sidebar");
  return (
    <nav className={styles.navigation} aria-label={tSidebar("mainNavigation")}>
      {navigation.map((item) => (
        <NavigationLink
          key={item.href}
          item={item}
          label={tNavigation(item.labelKey)}
          pathname={pathname}
          collapsed={collapsed}
          onNavigate={onNavigate}
        />
      ))}
    </nav>
  );
}

function Sidebar({
  pathname,
  collapsed,
  onToggleCollapsed,
}: {
  pathname: string;
  collapsed: boolean;
  onToggleCollapsed(): void;
}) {
  const t = useTranslations("shell.sidebar");
  return (
    <div className={styles.sidebarBody}>
      <div className={styles.brandRow}>
        <AvenBrand />
      </div>

      <SidebarNavigation pathname={pathname} collapsed={collapsed} />

      <div className={styles.sidebarFooter}>
        <Divider />
        <div className={styles.sidebarUtility}>
          <IconButton
            aria-label={collapsed ? t("expand") : t("collapse")}
            tooltip={collapsed ? t("expand") : t("collapse")}
            onClick={onToggleCollapsed}
            aria-expanded={!collapsed}
            aria-controls="aven-desktop-sidebar"
          >
            {collapsed ? (
              <ChevronRight {...iconDefaults} aria-hidden="true" />
            ) : (
              <ChevronLeft {...iconDefaults} aria-hidden="true" />
            )}
          </IconButton>
          <span className={styles.collapseLabel}>{t("collapse")}</span>
        </div>
      </div>
    </div>
  );
}

function ThemeControl() {
  const t = useTranslations("shell.theme");
  const { theme, setTheme } = useTheme();
  const current = themeOptions.find((option) => option.value === theme) ?? themeOptions[2];
  const CurrentIcon = current.icon;

  return (
    <DropdownMenu>
      <DropdownMenuTrigger className={styles.topbarControl} aria-label={t("current", { theme: t(current.value) })}>
        <CurrentIcon {...iconDefaults} aria-hidden="true" />
        <span className={styles.topbarControlLabel}>{t(current.value)}</span>
        <ChevronDown {...iconDefaults} size={iconSizes.sm} aria-hidden="true" />
      </DropdownMenuTrigger>
      <DropdownMenuContent className={styles.themeMenu} aria-label={t("select")}>
        {themeOptions.map((option) => {
          const Icon = option.icon;
          const label = t(option.value);
          return (
            <DropdownMenuItem
              key={option.value}
              icon={<Icon {...iconDefaults} aria-hidden="true" />}
              onClick={() => setTheme(option.value)}
              aria-label={theme === option.value ? t("optionSelected", { option: label }) : label}
            >
              <span className={styles.themeMenuLabel}>{label}</span>
              {theme === option.value && <Check {...iconDefaults} size={iconSizes.sm} aria-hidden="true" />}
            </DropdownMenuItem>
          );
        })}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

function getInitials(value: string) {
  const words = value.trim().split(/\s+/).filter(Boolean);
  if (!words.length) return "?";
  return words.slice(0, 2).map((word) => word[0]?.toUpperCase()).join("");
}

function UserControl({
  user,
  leaving,
  onLogout,
}: Pick<ApplicationShellProps, "user" | "leaving" | "onLogout">) {
  const t = useTranslations("shell.user");
  const displayName = user?.name || user?.full_name || user?.email || null;
  const secondary = user?.email && user.email !== displayName ? user.email : user?.role;
  const identityLabel = displayName || t("authenticatedAccount");
  const initials = displayName ? getInitials(displayName) : "?";

  return (
    <DropdownMenu>
      <DropdownMenuTrigger className={styles.userTrigger} aria-label={t("menu")}>
        <Avatar fallback={initials} alt={identityLabel} size="sm" />
        {(displayName || secondary) && (
          <span className={styles.userTriggerCopy}>
            {displayName && <strong>{displayName}</strong>}
            {secondary && <small>{secondary}</small>}
          </span>
        )}
        <ChevronDown {...iconDefaults} size={iconSizes.sm} aria-hidden="true" />
      </DropdownMenuTrigger>
      <DropdownMenuContent className={styles.userMenu} aria-label={t("actions")}>
        <div className={styles.userSummary}>
          <strong>{identityLabel}</strong>
          {secondary && <span>{secondary}</span>}
        </div>
        <DropdownMenuSeparator />
        <DropdownMenuItem
          danger
          disabled={leaving}
          icon={<LogOut {...iconDefaults} aria-hidden="true" />}
          onClick={() => void onLogout()}
        >
          {leaving ? t("signingOut") : t("signOut")}
        </DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

function Topbar({
  user,
  leaving,
  onLogout,
  onOpenMobileNavigation,
}: Pick<ApplicationShellProps, "user" | "leaving" | "onLogout"> & {
  onOpenMobileNavigation(): void;
}) {
  const t = useTranslations("shell.sidebar");
  return (
    <header className={styles.topbar}>
      <div className={styles.topbarLeading}>
        <IconButton
          className={styles.mobileMenuTrigger}
          aria-label={t("open")}
          tooltip={t("open")}
          onClick={onOpenMobileNavigation}
        >
          <Menu {...iconDefaults} size={iconSizes.xl} aria-hidden="true" />
        </IconButton>
        <div className={styles.mobileBrand}>
          <AvenBrand compact />
        </div>
      </div>

      <div className={styles.topbarUtilities}>
        <ThemeControl />
        <LanguageControl />
        <UserControl user={user} leaving={leaving} onLogout={onLogout} />
      </div>
    </header>
  );
}

export function ApplicationShell({
  children,
  user,
  leaving = false,
  statusMessage,
  onLogout,
}: ApplicationShellProps) {
  const pathname = usePathname();
  const t = useTranslations("shell");
  const [collapsed, setCollapsed] = useState(false);
  const [mobileOpen, setMobileOpen] = useState(false);

  useEffect(() => {
    let saved: string | null = null;
    try {
      saved = window.localStorage.getItem(SIDEBAR_STORAGE_KEY);
    } catch {
      saved = null;
    }
    const next = parseSidebarCollapsed(saved);
    setCollapsed(next);
    document.documentElement.dataset.sidebar = next ? "collapsed" : "expanded";
  }, []);

  useEffect(() => {
    setMobileOpen(false);
  }, [pathname]);

  function toggleSidebar() {
    const next = !collapsed;
    setCollapsed(next);
    document.documentElement.dataset.sidebar = next ? "collapsed" : "expanded";
    try {
      window.localStorage.setItem(SIDEBAR_STORAGE_KEY, serializeSidebarCollapsed(next));
    } catch {
      // Navigation remains functional when local persistence is unavailable.
    }
  }

  return (
    <div className={styles.shell}>
      <a className={styles.skipLink} href="#main-content">{t("accessibility.skipToContent")}</a>

      <aside id="aven-desktop-sidebar" className={styles.desktopSidebar} aria-label={t("sidebar.mainNavigation")}>
        <Sidebar pathname={pathname} collapsed={collapsed} onToggleCollapsed={toggleSidebar} />
      </aside>

      <div className={styles.workspace}>
        <Topbar
          user={user}
          leaving={leaving}
          onLogout={onLogout}
          onOpenMobileNavigation={() => setMobileOpen(true)}
        />

        <main id="main-content" tabIndex={-1} className={styles.mainContent}>
          <div className={styles.contentFrame}>
            {statusMessage && <p className={styles.shellError} role="alert">{statusMessage}</p>}
            {children}
          </div>
        </main>
      </div>

      <Drawer open={mobileOpen} onOpenChange={setMobileOpen}>
        <DrawerContent side="left" className={styles.mobileDrawer} aria-label={t("sidebar.mobileNavigation")}>
          <div className={styles.mobileSidebar}>
            <div className={styles.mobileBrandRow}>
              <AvenBrand compact />
            </div>
            <SidebarNavigation
              pathname={pathname}
              collapsed={false}
              onNavigate={() => setMobileOpen(false)}
            />
          </div>
        </DrawerContent>
      </Drawer>
    </div>
  );
}
